(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-flow-matching-sampler"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-1\">一 · 线上事故：少步采样把画质压垮的那一夜</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-2\">二 · 它解决的具体推理问题：把「积分弯曲流」换成「积分近似直线」</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-3\">三 · 它不解决什么：三条明确的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-4\">四 · 机制走一遍：从请求进入到 VAE 解码的数据流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-5\">五 · 一个具体例子：6 步 Euler 与 12 步中点法的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-6\">六 · 适用边界的工程化表达</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-7\">七 · 当四步出图把纹理抹平：整流流匹配的失效面与代价账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-8\">八 · 请求进入与 latent 初始化：第一步的显存与带宽账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-9\">九 · timestep 表与条件拼接：调度器的离散化决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-10\">十 · DiT 前向与速度场输出：每步的真实代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-11\">十一 · Euler 更新与中点法修正：步数与阶数的权衡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-12\">十二 · 终态解码与流水线衔接：x_0 之后的事</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-13\">十三 · 整流流采样器的失效边界：从 latent 采样到 VAE 解码的逐步代价审计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-14\">十四 · 直线插值的逐项拆解：$x_t$ 为何是“可积的直线”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-15\">十五 · 速度场参数化与 CFG 合并的次序约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-16\">十六 · 离散 timestep 表与步长 $\\Delta$ 的选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-17\">十七 · 量化叠加下的速度场精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-18\">十八 · 二阶修正的收益边界与实现代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-19\">十九 · 失败模式的公式定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-20\">二十 · 直线假设失效时的二阶代价与分层步数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-21\">二十一 · 请求形态与批大小的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-22\">二十二 · 长度分布决定步数分层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-23\">二十三 · 并发模型与 SLO 的张力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-24\">二十四 · 负载不对时的三种失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-25\">二十五 · 配方表的工程落地</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-26\">二十六 · 分桶调度与步数对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-27\">二十七 · 负载配方：直线轨迹的适用域与失配代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-28\">二十八 · 硬件档位：把每步前向次数当作第一约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-29\">二十九 · 并行拓扑：CFG 合并决定了并行维度的形状</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-30\">三十 · 量化方案：速度场输出的数值敏感度分层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-31\">三十一 · KV 策略：这里没有 KV cache，但有等价的状态预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-32\">三十二 · 调度参数：步数分层与阶数分层是同一件事</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-33\">三十三 · 一个可复现的配置思路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-34\">三十四 · 部署配方的失效边界与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-35\">三十五 · 每步前向次数：时延的第一性成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-36\">三十六 · 激活峰值与中间量：显存先于算力崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-37\">三十七 · 带宽：权重流与激活流的两种压力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-38\">三十八 · 通信：张量并行下的每步同步点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-39\">三十九 · 功耗与尾延迟：稳态之外的账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-40\">四十 · 直线轨迹撞上系统墙：每步前向、激活峰值与尾延迟的三重约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-41\">四十一 · 规模放大后先崩在哪：每步前向次数、激活峰值与尾延迟的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-42\">四十二 · 精度失效：弯曲轨迹的三种可观测征兆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-43\">四十三 · OOM 与显存峰值的定位路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-44\">四十四 · 批抖动与路由不均的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-45\">四十五 · 尾延迟尖刺的来源与监控</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-46\">四十六 · 回滚的工程判断与灰度边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-47\">四十七 · 少步直线假设失效时的诊断与回退路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-48\">四十八 · 同族谱系与选择轴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-49\">四十九 · 与 DDIM 的对照：弯曲流与直线流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-50\">五十 · 与 LCM 一致性蒸馏的对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-51\">五十一 · 与高阶求解器的对照：阶数换步数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-52\">五十二 · 决策表与适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-53\">五十三 · 组合与降级路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-flow-matching-sampler-sec-54\">五十四 · 选型边界：整流流匹配在算法族中的位置与失效面</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:493px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 493.2 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"411.2\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入，latent 从标准高斯采样，timestep 从 1 递减到 0</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"411.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条件 embedding 与 latent 拼接送入 DiT，网络输出速度…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"411.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">Euler 更新 x_{t-Δ} = x_t − Δ·v_θ，或中点法做二…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"411.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按 scheduler 的离散 timestep 表迭代 4–20 步</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"411.2\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">终态 x_0 送入 VAE 解码输出图像</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-flow-matching-sampler-sec-1\">一 · 线上事故：少步采样把画质压垮的那一夜</h3>\n<p>某在线文生图服务在扩容后把默认采样步数从 30 步下调到 6 步，理由是「单请求时延必须压进 SLO 预算」。上线当晚监控没有报错，GPU 利用率平稳，队列深度正常，但用户侧投诉集中爆发：人像的皮肤纹理糊成一片，建筑边缘出现锯齿状涂抹，复杂 prompt（多主体、指定构图、文字排版）几乎全部退化。运维排查后发现，问题不在显存溢出、不在 NCCL 超时，也不在量化精度——而是采样器本身在少步下失效：沿弯曲概率流做数值积分时，离散化误差随步数减少被迅速放大，6 步的 Euler 更新根本跟不上轨迹的曲率。这个事故的教训是：**步数不是可以随意拧小的旋钮，它是算法与轨迹几何之间的契约**。整流流匹配采样器正是为撕毁这份旧契约、重签一份新契约而存在的。</p>\n<p>先把问题定义清楚。扩散模型的采样本质是求解一个概率流 ODE：从标准高斯先验出发，沿时间把噪声输运到数据分布。若概率流是弯曲的，数值求解器必须用小步长、多步数才能把积分误差控制在画质可接受范围内。服务端面对的约束是硬的：单请求时延 = 步数 × 每步前向时延，而每步前向时延又受 DiT 的算力、显存带宽与批大小制约。于是形成一个死结——要画质就得多步，要多步就超时延。整流流匹配的切入点不是把求解器做得更聪明，而是**改变被积分的对象**：用直线插值把噪声到数据的传输拉直成近似直线轨迹，让少步 Euler 的离散误差天然变小。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-2\">二 · 它解决的具体推理问题：把「积分弯曲流」换成「积分近似直线」</h3>\n<p>整流流匹配的训练目标是把速度场重参数化为直线插值的斜率。给定数据样本 $x_0$ 与标准高斯噪声 $\\epsilon$，插值路径定义为 $x_t = (1-t)\\,x_0 + t\\,\\epsilon$，$t\\in[0,1]$。对 $t$ 求导得到这条直线的速度：$\\frac{dx_t}{dt} = \\epsilon - x_0$，它与 $t$ 无关，是常数。训练时让 DiT 拟合 $v_\\theta(x_t,t,c)\\approx \\epsilon - x_0$，推理时只需沿这条近似直线做 Euler 更新：</p>\n<div class=\"formula\">$$x_{t-\\Delta} = x_t - \\Delta\\,v_\\theta(x_t,t,c)$$</div>\n<p>关键在于误差结构的变化。对弯曲流，Euler 的单步截断误差正比于轨迹的二阶导（曲率），步数减少时误差按步长线性放大后又被曲率放大；对直线流，二阶导近似为零，单步误差退化为高阶小量，于是 4–8 步就能逼近多步 DDIM 的画质。这就是它解决的具体推理问题：**在固定时延预算下，把「步数不足导致的画质崩塌」转化为「直线化不足导致的纹理模糊」**——后者是渐进的、可分层缓解的，前者是断崖式的、不可控的。</p>\n<p>代价必须说清楚。直线化依赖训练分布：训练时见过的条件复杂度与分辨率区间内，轨迹接近直线；一旦越界（复杂多主体 prompt、超高分辨率、罕见风格），轨迹重新弯曲，少步 Euler 立刻退化为纹理模糊。这不是实现缺陷，而是算法边界。系统侧的代价同样具体：二阶中点法每步要做两次前向（一次在 $x_t$ 处取斜率，一次在半步处修正），每步前向次数翻倍，单请求时延与激活显存峰值同步上升；调度器若不做阶数与步数的联合权衡，时延预算会被二阶修正吃掉。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-3\">三 · 它不解决什么：三条明确的失效边界</h3>\n<p>第一条边界是**训练分布外的条件复杂度**。整流流不是万能加速器，它把画质押在「训练时轨迹被拉直的程度」上。复杂条件（多主体空间关系、精确文字渲染、强风格约束）在高分辨率下轨迹仍有弯曲，4–8 步 Euler 输出纹理模糊。工程判断是分层选步数：按分辨率档位与 prompt 复杂度分桶，简单桶走 4–6 步，复杂桶回退到 10–20 步或切二阶求解器，而不是全局统一压步数。</p>\n<p>第二条边界是**它不替代蒸馏类方法**。与 LCM 一致性蒸馏相比，整流流是训练目标的重参数化，不需要教师轨迹数据、不需要两阶段蒸馏管线，训练目标简单、收敛稳定；但它也不具备蒸馏方法那种把步数压到 1–4 步的能力，少步画质的上限由训练分布直线化程度决定。二者不是替代关系，而是不同预算档位的工具。</p>\n<p>第三条边界是**它与 CFG 的耦合是脆弱的**。速度场参数化与 CFG 合并天然兼容，但前提是合并顺序正确、guidance scale 稳定。若把条件与无条件速度场的合并顺序写错，或在批内让 guidance scale 漂移，直线插值假设就被破坏，少步输出会出现结构噪声与语义偏离——这类故障不报错、不掉帧，只在画质上体现，是最难定位的一类。事故复盘里那条「语义偏离」的投诉，根源就在这里。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-4\">四 · 机制走一遍：从请求进入到 VAE 解码的数据流</h3>\n<p>请求进入后，latent 从标准高斯采样，timestep 从 1 递减到 0。条件 embedding 与 latent 拼接送入 DiT，网络输出速度场 $v_\\theta(x_t,t,c)$；Euler 更新按 $x_{t-\\Delta}=x_t-\\Delta\\,v_\\theta$ 推进，或中点法做二阶修正；按 scheduler 的离散 timestep 表迭代 4–20 步；终态 $x_0$ 送入 VAE 解码输出图像。整条链路上，整流流只改变了「速度场拟合什么」与「积分走多直的路」，其余环节（条件编码、VAE、批调度）不变。</p>\n<p>系统代价按环节拆开看：DiT 前向是时延主项，步数直接线性放大它；二阶中点法把每步前向次数翻倍，时延与显存开销同步上升；显存按 4–20 步迭代的激活峰值配置，二阶求解器还需保留中间量做修正，峰值更高。批大小按显存与步数迭代组织——步数越多，可容纳的批越小，吞吐与时延在此消彼长。量化可与 FP8/FP4 叠加，速度场参数化与 CFG 合并天然兼容，这意味着整流流可以和低精度 GEMM 共存，但精度损失会叠加在少步误差上，需要联合评估而非各自独立调参。</p>\n<table class=\"mini\"><thead><tr><th>配置档位</th><th>步数</th><th>求解器</th><th>时延主项</th><th>显存峰值</th><th>画质风险</th></tr></thead><tbody><tr><td>低时延桶</td><td>4–6</td><td>Euler</td><td>步数 × 单次前向</td><td>低</td><td>复杂 prompt 纹理模糊</td></tr><tr><td>均衡桶</td><td>8–12</td><td>Euler</td><td>步数 × 单次前向</td><td>中</td><td>高分辨率边缘退化</td></tr><tr><td>高保真桶</td><td>10–20</td><td>中点法</td><td>2 × 步数 × 单次前向</td><td>高（保留中间量）</td><td>时延超预算</td></tr></tbody></table>\n<p>这张表本身就是工程判断：桶的划分依据不是步数本身，而是分辨率与 prompt 复杂度这两个直线化程度的代理变量。把桶划错，等于把事故重演一遍。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-5\">五 · 一个具体例子：6 步 Euler 与 12 步中点法的取舍</h3>\n<p>设单次 DiT 前向在给定批大小下耗时 $T_f$，Euler 的 6 步单请求时延约为 $6T_f$，中点法 12 步约为 $24T_f$——四倍差距。若 SLO 预算是 $8T_f$，那么 6 步 Euler 是唯一可行档位，但它在复杂 prompt 上画质不达标；此时正确的工程动作不是硬压步数，而是把复杂 prompt 路由到更高预算队列，或对该桶改用 8 步 Euler 加分辨率降档。反过来，若预算宽裕到 $24T_f$，中点法的二阶修正能把高分辨率下的弯曲轨迹误差压下去，代价是显存峰值上升、批大小收缩、吞吐下降。</p>\n<p>这里的核心判断是：**整流流把「步数—画质」曲线从断崖变成斜坡，但斜坡的斜率由训练分布决定，不由调度器决定**。调度器能做的是在斜坡上选点，不能改变斜坡本身。事故的根因正是把斜坡当成了平地。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-6\">六 · 适用边界的工程化表达</h3>\n<p>适用区间可以写成一句可执行的判据：4–20 步、条件复杂度中等的在线服务，整流流匹配是默认选择；复杂条件或高分辨率下轨迹弯曲，少步出现纹理模糊，必须增加步数或切二阶求解器；规模上限受每步前向次数与显存峰值约束，二阶求解器时延开销更高，需按 SLO 在步数与阶数间权衡。量化叠加时，低精度 GEMM 的数值误差与少步离散误差会耦合，评估必须端到端做，不能分项验收。</p>\n<p>最后落在机制上：整流流匹配的推理正确性依赖一个隐含契约——速度场在推理时确实近似常数 $\\epsilon - x_0$。所有工程配置（步数分桶、阶数选择、CFG 合并顺序、量化档位）都是在维护这份契约。一旦某个配置让 $v_\\theta$ 的输出偏离直线斜率，少步误差就不再是「纹理模糊」这种可容忍退化，而是结构噪声与语义偏离。因此上线前的验收项不是「跑通」，而是「在目标分辨率与 prompt 分布上验证直线化残差」——这才是把事故挡在门外的具体机制。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-7\">七 · 当四步出图把纹理抹平：整流流匹配的失效面与代价账</h3>\n<p>线上事故的形态很具体：一个在线文生图服务把默认采样步数从 20 压到 4，用 Euler 沿整流流速度场积分，P99 时延达标，但客诉集中在“毛发、织物、远景文字糊成一片”。根因不是算子或量化，而是直线化假设在复杂 prompt 与高分辨率下不成立——训练分布没能把噪声到数据的传输拉得足够直，轨迹残余弯曲在 Δ 较大时被 Euler 一阶离散化直接放大。误差量级可写成局部截断项 <span>‖x_{t−Δ} − x*_{t−Δ}‖ ≈ ½Δ²‖dv_θ/dt‖</span>，曲率项 ‖dv_θ/dt‖ 越大，少步误差越难压住；这与 DDIM 沿弯曲概率流积分遇到的困境同源，区别只在于整流流把弯曲程度挪进了训练目标里。它解决的是“少步下离散化误差迅速放大”这一服务端矛盾，不解决训练分布之外的曲率。</p>\n<p>边界因此可以画得很硬：适合 4–20 步、条件复杂度中等的在线服务；一旦 prompt 含密集空间结构或多主体绑定，或分辨率抬到需要更多高频细节的档位，就必须按分辨率与 prompt 复杂度分层选步数，否则 4–8 步 Euler 的画质不达标。它也不替代蒸馏路线——与 LCM 一致性蒸馏相比，整流流是训练目标重参数化，不需要教师轨迹数据，但少步画质直接绑定训练分布的直线化程度，分布漂移（新风格 LoRA、领域微调）会立刻反映为纹理模糊。速度场与 CFG 合并顺序错位、guidance scale 漂移同样会破坏直线插值假设，少步输出出现结构噪声与语义偏离，这类故障在日志上表现为时延正常而画质指标塌陷，最难定位。</p>\n<table class=\"mini\"><thead><tr><th>配置</th><th>每步前向</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>4–8 步 Euler</td><td>1×</td><td>激活峰值低，时延最优</td><td>复杂条件/高分辨率纹理模糊</td></tr><tr><td>中点法二阶</td><td>2×</td><td>时延与显存上升，需留中间量</td><td>未按 SLO 权衡阶数则超时延预算</td></tr><tr><td>增加步数至 20</td><td>1×</td><td>时延线性增长</td><td>吞吐被批大小挤占</td></tr></tbody></table>\n<p>系统代价必须按 SLO 结账：二阶中点法每步前向次数翻倍，单请求时延与激活显存同步上升，因为修正需要保留 x_t 与 v_θ 的中间量；在张量并行档位上，这意味着每步的通信次数与显存峰值都翻倍，批大小被迫下调，吞吐反而可能低于多步 Euler。工程判断是：把步数与阶数当作两个独立旋钮，按分辨率与 prompt 复杂度分桶配置——低复杂度桶走 4 步 Euler 吃吞吐，高复杂度桶走 8 步 Euler 或中点法保画质，并用离线画质回归集守住分桶阈值，而不是全局压步数。</p>\n<h3 id=\"alg-flow-matching-sampler-sec-8\">八 · 请求进入与 latent 初始化：第一步的显存与带宽账</h3>\n<p>整流流匹配采样器的第一步不是网络前向，而是把请求变成一块可被 DiT 消费的 latent 张量。请求进入调度器后，先完成 prompt 编码与条件 embedding 的落地，随后从标准高斯分布采样 <span class=\"inline\">x_1 ~ N(0, I)</span>，形状为 <span class=\"inline\">[B, C, H, W]</span>（潜空间分辨率，非像素分辨率）。这一步的输入是请求元数据（prompt、分辨率、步数档位、guidance scale），输出是 latent 张量与条件张量，二者在后续每一步都要被拼接送入 DiT。</p>\n<p>代价集中在显存与带宽而非算力。latent 本身很小，但条件 embedding 与 CFG 的两份（或合并后的一份）条件张量要常驻；在 Blackwell 上，这一步的瓶颈是 HBM 到 SMEM 的搬运与 kernel launch 开销，而不是浮点吞吐。工程上要把 latent 初始化与条件编码放进同一个 CUDA graph 捕获区间，避免每请求的 launch 抖动。一个具体例子：在线文生图服务里，若把条件编码放在请求线程同步做，单请求首 token 时延会被编码 kernel 的冷启动拉长；把编码器预热并纳入图捕获后，初始化阶段退化为一次显存写。注意 latent 的 dtype 选择要与后续 DiT 的数值精度路径一致——若 DiT 走 FP8/FP4 混合精度，latent 在进入网络前需按块量化，这一步的量化开销要计入首步时延，而不是摊到 4–20 步里。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-9\">九 · timestep 表与条件拼接：调度器的离散化决策</h3>\n<p>timestep 从 1 递减到 0，但推理时并不连续积分，而是按 scheduler 给出的离散 timestep 表迭代 4–20 步。输入是步数档位与调度器类型（均匀、偏移或按信噪比重排），输出是一张长度为 N 的 <span class=\"inline\">{t_i}</span> 表与对应的步长 <span class=\"inline\">Δ_i = t_i − t_{i+1}</span>。这张表决定了整条直线轨迹被切成几段，直接决定离散化误差的量级。</p>\n<p>条件拼接发生在每次前向之前：条件 embedding 与当前 latent 在通道维或 token 维拼接，形成 DiT 的输入。代价是每步一次拼接 kernel 与一次条件张量的读带宽；若 CFG 未合并，条件张量要读两份，显存带宽翻倍。整流流的速度场参数化与 CFG 合并天然兼容，因此工程上优先在条件侧做 batch 合并而非在输出侧做两次前向——这把每步的前向次数从 2 降到 1，是少步场景下最直接的时延削减。一个具体例子：guidance scale 漂移会破坏直线插值假设，表现为少步输出出现结构噪声与语义偏离；因此 guidance scale 必须在 timestep 表生成时冻结，不能在迭代中途按请求动态调整。</p>\n<div class=\"formula\">$$x_t = (1-t)\\,x_0 + t\\,\\epsilon,\\quad v_\\theta(x_t,t,c)\\approx \\epsilon - x_0,\\quad x_{t-\\Delta}=x_t-\\Delta\\,v_\\theta(x_t,t,c)$$</div>\n\n<h3 id=\"alg-flow-matching-sampler-sec-10\">十 · DiT 前向与速度场输出：每步的真实代价</h3>\n<p>这是整条流水线里唯一的重计算步骤。输入是拼接后的 latent-条件张量，输出是速度场 <span class=\"inline\">v_θ(x_t, t, c)</span>，其监督目标在训练时是 <span class=\"inline\">ε − x_0</span>，即直线插值的切向量。网络内部走 Blackwell 的 tcgen05 MMA 与 TMEM 路径，注意力与 GEMM 的精度档位由部署配方决定；这部分机制在 DiT FP8 注意力与 NVFP4 混合精度条目里已展开，此处只算代价。</p>\n<p>每步代价 = 一次完整 DiT 前向的算力 + 激活峰值显存 + 权重读带宽。少步场景下，权重读带宽往往压过算力：4 步意味着权重只被读 4 次，若权重未做 FP8/FP4 压缩，单请求的字节搬运量相对于其 FLOPs 偏高，算术强度不足。因此量化与少步是耦合的——步数越少，越要把权重压到低精度以提升每步的有效吞吐。激活峰值显存则按 4–20 步迭代配置，二阶求解器还要额外保留中间量做修正，峰值更高。一个具体例子：同一张卡上，4 步 Euler 的激活峰值可容纳更大批大小，而中点法因需保留 <span class=\"inline\">v_θ(x_t,t)</span> 与预测的 <span class=\"inline\">x_{t−Δ/2}</span> 做二阶修正，批大小必须下调，吞吐随之下降。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-11\">十一 · Euler 更新与中点法修正：步数与阶数的权衡</h3>\n<p>Euler 更新的输入是当前 latent 与速度场输出，输出是下一步 latent：<span class=\"inline\">x_{t−Δ} = x_t − Δ·v_θ(x_t,t,c)</span>。这是一次逐元素的线性组合，算力可忽略，代价在显存读写——每步要把整块 latent 读一遍写一遍，步数越多，这部分带宽开销越不可忽视。中点法做二阶修正：先以半步长走一次得到预测中点，再在中点处求速度场，用中点速度走完整步。输入多了一次前向，输出精度更高，代价是每步前向次数翻倍。</p>\n<p>权衡的判据是 SLO。在线文生图以单请求时延为主，4–8 步 Euler 即可接近多步 DDIM 画质，是默认档位；当分辨率升高或 prompt 复杂度上升、训练分布直线化不足导致轨迹仍弯曲时，4–8 步 Euler 会出现纹理模糊，此时要么加步数，要么换中点法。二阶求解器的时延与显存开销上升，未按 SLO 权衡阶数与步数时单请求时延会超出预算。一个具体例子：分层选步数——低分辨率、简单 prompt 走 4 步 Euler；高分辨率、复杂条件走 8 步 Euler 或 4 步中点法，用阶数换步数，把前向总次数控制在预算内。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-12\">十二 · 终态解码与流水线衔接：x_0 之后的事</h3>\n<p>迭代收敛后得到终态 <span class=\"inline\">x_0</span>，送入 VAE 解码输出图像。这一步的输入是潜空间张量，输出是像素张量，代价是解码器的算力与显存——VAE 解码在像素分辨率上做卷积，其激活峰值常与 DiT 前向同量级，是整条流水线的第二个显存峰值。工程上要把 DiT 迭代与 VAE 解码的显存峰值分开核算，不能只按 DiT 配置批大小；VAE 分块并行解码是控制这一峰值的常规手段。</p>\n<p>流水线衔接的关键是终态 latent 的 dtype 与布局。若 DiT 输出为低精度，解码前需按 VAE 的输入精度还原，这一步的反量化开销要计入尾段时延。另一个衔接点是请求级流水：终态 <span class=\"inline\">x_0</span> 一旦产出即可释放 DiT 侧的激活与 KV 类中间量，把显存让给下一批请求的解码，这是连续批处理在扩散服务里的落点。一个具体例子：把解码与下一请求的 latent 初始化重叠，用异步流把 VAE 解码放在独立 stream 上，可使解码时延被下一请求的首步前向掩盖，提升整体吞吐而不改变单请求时延。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>latent 初始化</td><td>请求元数据、条件 embedding</td><td>x_1、条件张量</td><td>显存常驻、launch 开销</td></tr><tr><td>timestep 表</td><td>步数档位、调度器</td><td>{t_i}、Δ_i</td><td>可忽略算力，决策性开销</td></tr><tr><td>DiT 前向</td><td>拼接 latent-条件</td><td>v_θ</td><td>算力、权重带宽、激活峰值</td></tr><tr><td>Euler/中点更新</td><td>x_t、v_θ</td><td>x_{t−Δ}</td><td>latent 读写带宽；中点法前向翻倍</td></tr><tr><td>VAE 解码</td><td>x_0</td><td>像素图像</td><td>解码算力、第二显存峰值</td></tr></tbody></table>\n<p>把五步的代价按请求/token/KV 流动顺序排开，可以看到整流流匹配采样器的时延结构是“一次初始化 + N 次重前向 + 一次解码”，其中 N 由 scheduler 表决定，重前向的权重带宽与激活峰值是主约束，Euler 更新的 latent 读写是随步数线性增长的次约束。稳定性上，直线化依赖训练分布，复杂条件/高分辨率下轨迹仍有弯曲，需按分辨率与 prompt 复杂度分层选步数；速度场与 CFG 合并顺序错位或 guidance scale 漂移会破坏直线插值假设，必须在 timestep 表生成时冻结合并顺序与 scale。规模上限受每步前向次数与显存峰值约束，二阶求解器时延开销更高，因此在 SLO 收紧时应优先降阶数而非降步数——4 步 Euler 的离散误差在直线轨迹上可控，而 2 步中点法的二阶修正虽精度更高，前向总次数与 4 步 Euler 相同却多一份中间量显存，收益并不总是正。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-13\">十三 · 整流流采样器的失效边界：从 latent 采样到 VAE 解码的逐步代价审计</h3>\n<p>把整流流采样器的五个步骤按数据流拆开看，每一步的代价结构并不相同，而失效点往往不在计算最重的那一步。第一步是 latent 采样：请求进入后从标准高斯抽取 $x_1$，形状由分辨率与通道数决定，代价是显存占用而非算力，在批大小按显存组织时这一块是静态峰值的一部分。第二步是条件 embedding 与 latent 拼接送入 DiT，文本编码器与拼接操作本身不构成瓶颈，但它决定了后续速度场是否落在训练分布内——复杂 prompt 与高分辨率下，条件分布偏离训练时的直线化假设，轨迹开始弯曲，这是少步 Euler 出现纹理模糊的根源，而非求解器本身的问题。第三步是 DiT 前向输出 $v_\\theta(x_t,t,c)$，这是唯一随步数线性放大的算力项，4–20 步迭代意味着 4–20 次完整前向，激活峰值按此配置显存；二阶中点法在每步内做两次前向再取平均修正，前向次数翻倍，单请求时延与激活峰值同步上升，这是阶数与步数必须按 SLO 权衡的直接原因。</p>\n<p>第四步是 scheduler 驱动的离散 timestep 表迭代。Euler 更新 $x_{t-\\Delta}=x_t-\\Delta\\,v_\\theta(x_t,t,c)$ 的单步误差正比于 $\\Delta^2$ 乘以轨迹曲率，直线化充分时曲率小，$\\Delta$ 取大步仍可控；一旦条件复杂导致曲率抬头，同样的 $\\Delta$ 下误差迅速累积，此时唯一的补救是缩小 $\\Delta$ 即增加步数，或改用中点法把局部误差降到更高阶。这里存在一个明确的工程判断：步数分层必须按分辨率与 prompt 复杂度做，而不是全局固定 4–8 步。高分辨率请求的 latent 维度更大，单位步长内速度场变化更剧烈，固定少步会系统性欠采样；反之简单 prompt 下强行加步只是浪费前向预算。第五步终态 $x_0$ 送入 VAE 解码，解码是一次固定开销的前向，与步数无关，但在批调度中它与 DiT 迭代争抢同一张卡的显存与带宽，连续批处理下解码阶段会打断迭代阶段的流水，形成尾延迟。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入→输出</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>latent 采样</td><td>形状参数→$x_1$</td><td>显存静态占用</td><td>批大小超显存预算</td></tr><tr><td>条件拼接+DiT</td><td>$x_t,t,c$→$v_\\theta$</td><td>算力随步数线性增长</td><td>条件偏离训练分布，轨迹弯曲</td></tr><tr><td>Euler/中点更新</td><td>$x_t,v_\\theta$→$x_{t-\\Delta}$</td><td>二阶法前向翻倍</td><td>$\\Delta$ 过大且曲率高</td></tr><tr><td>timestep 迭代</td><td>离散表→$x_0$</td><td>4–20 次前向的时延</td><td>步数未按复杂度分层</td></tr><tr><td>VAE 解码</td><td>$x_0$→图像</td><td>固定前向+显存争抢</td><td>与迭代阶段流水冲突</td></tr></tbody></table>\n<p>还有一类失效不属于数值误差而属于参数化错位：速度场与 CFG 合并的顺序若与训练时不一致，或 guidance scale 在请求间漂移，直线插值假设被破坏，少步输出会出现结构噪声与语义偏离——这种失败不会随步数增加而消失，加步只是把错误轨迹积分得更精细。因此在服务端，整流流采样器的容量规划不能只按平均步数估算吞吐，必须把二阶求解器的前向翻倍、解码阶段的显存争抢、以及按复杂度分层带来的步数方差一起计入；规模上限由每步前向次数与激活峰值共同约束，而非单纯由 DiT 参数量决定。</p>\n<h3 id=\"alg-flow-matching-sampler-sec-14\">十四 · 直线插值的逐项拆解：$x_t$ 为何是“可积的直线”</h3>\n<p>核心插值式 $x_t=(1-t)x_0+t\\epsilon$ 把 $t$ 当作几何参数而非扩散噪声调度：$t=0$ 落在数据端，$t=1$ 落在标准高斯端，两端之间是一条线段。对 $t$ 求导立刻得到 $\\frac{dx_t}{dt}=\\epsilon-x_0$，这是一个与 $t$ 无关的常向量——这正是“整流”二字的全部含义：给定一对 $(x_0,\\epsilon)$，其传输速度在整个区间上恒定。于是训练目标不必再预测随时间变化的噪声水平，而是直接回归这个常向量：$v_\\theta(x_t,t,c)\\approx\\epsilon-x_0$。逐项看：$x_0$ 是 VAE 潜空间里的数据样本，$\\epsilon$ 是标准高斯采样，$c$ 是条件 embedding；$t$ 同时充当网络的时间输入与插值系数，二者必须严格一致，否则网络看到的“时刻”与轨迹上的真实位置错位，速度场回归就失去几何意义。</p>\n<p>推导的关键一步在于把概率流 ODE 的积分从弯曲路径换成直线路径后，积分退化为一次乘法。对 $\\frac{dx_t}{dt}=v_\\theta$ 做一阶离散，得 $x_{t-\\Delta}=x_t-\\Delta\\,v_\\theta(x_t,t,c)$；由于真实速度沿直线恒定，这个 Euler 步的截断误差只来自网络对常向量的拟合残差，而不来自轨迹曲率。对比 DDIM 沿弯曲概率流积分，同样的 $\\Delta$ 下误差量级被曲率项主导，步数一少就迅速放大——这就是服务端“少步丢画质”的根源。代价上，这一步把每步的计算压到一次 DiT 前向：以潜空间分辨率 $H\\times W$ 计，单步激活峰值与 $H\\cdot W\\cdot d$ 成正比，4 步迭代的激活总量约为 20 步的五分之一，显存与带宽压力同步下降；但直线化只在训练分布覆盖的区域内成立，条件越复杂、分辨率越高，真实轨迹越偏离直线，残差项重新抬头。</p>\n<p>具体例子：在线文生图请求，$1024^2$ 输出对应 $128^2$ 潜空间，batch 按显存组织为 4–8；scheduler 给出 4–8 个离散 timestep，Euler 每步一次前向，末态 $x_0$ 直接进 VAE 解码。此时单请求时延由“步数 × 单步前向时延”线性决定，步数从 8 降到 4 即近似减半——这是整流流在 SLO 上最直接的杠杆，也是它相对多步 DDIM 的工程价值所在。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-15\">十五 · 速度场参数化与 CFG 合并的次序约束</h3>\n<p>把 $v_\\theta$ 参数化为 $\\epsilon-x_0$ 而不是噪声 $\\epsilon$，带来两个可实现的后果。其一，训练目标简单：给定配对样本，回归目标是一次减法，无需按噪声调度表重加权，收敛稳定，这也是它相对一致性蒸馏的差别——后者需要教师轨迹数据，而整流流只是训练目标的重参数化。其二，速度场与 CFG 天然兼容：CFG 在速度空间做线性外推 $v=v_\\text{uncond}+s\\,(v_\\text{cond}-v_\\text{uncond})$，由于 $v$ 是常向量，外推后的速度仍是常向量，直线假设不被破坏。但次序必须严格：先取无条件与有条件两次前向的速度，再合并，最后才做 Euler 更新；若先更新再合并，或 guidance scale $s$ 在迭代中漂移，等效速度场就不再对应同一条直线，少步输出会出现结构噪声与语义偏离。</p>\n<p>代价在这里体现为前向次数。CFG 合并意味着每步两次 DiT 前向（条件与无条件），若再叠加中点法二阶修正，每步前向次数再翻倍——单请求时延与显存开销同时上升，二阶求解器还需保留 $x_t$ 与中间速度做修正，激活峰值高于一阶。工程判断是：在 4–8 步区间优先用一阶 Euler 加 CFG 合并，把省下的前向预算留给分辨率或 batch；只有在 prompt 复杂度高、直线化不足时，才对少数请求切到中点法。伪代码思路可落到调度器层：</p>\n<div class=\"formula\">$$\\begin{aligned}\n&amp;x\\leftarrow\\mathcal{N}(0,I),\\ \\text{for } t \\text{ in } [1,\\dots,t_\\text{end}] \\text{ step } -\\Delta:\\\\\n&amp;\\quad v_u\\leftarrow v_\\theta(x,t,\\varnothing),\\quad v_c\\leftarrow v_\\theta(x,t,c)\\\\\n&amp;\\quad v\\leftarrow v_u+s\\,(v_c-v_u)\\\\\n&amp;\\quad x\\leftarrow x-\\Delta\\,v \\quad\\text{(Euler)}\\\\\n&amp;\\quad x_\\text{mid}\\leftarrow x+\\tfrac{\\Delta}{2}v,\\ v_2\\leftarrow v_\\theta(x_\\text{mid},t-\\tfrac{\\Delta}{2},c),\\ x\\leftarrow x-\\Delta\\,v_2 \\quad\\text{(中点法)}\n\\end{aligned}$$</div>\n<p>注意中点法里 $t-\\Delta/2$ 的时间输入必须与插值位置一致，否则二阶修正反而引入偏差；这也是二阶路径需要额外保存中间量的原因，显存换精度。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-16\">十六 · 离散 timestep 表与步长 $\\Delta$ 的选择</h3>\n<p>scheduler 的离散 timestep 表并非均匀切分那么简单：$t$ 从 1 递减到 0，$\\Delta$ 在端点附近的影响不对称。由于 $t=1$ 端是纯噪声、$t=0$ 端是数据，Euler 在噪声端的残差被后续步放大，在数据端的残差直接留在输出上。因此少步配置常把步长在两端收紧、中段放宽，用非均匀 $\\Delta_k$ 抵消直线化残差的空间分布。公式上，第 $k$ 步的更新是 $x_{k+1}=x_k-\\Delta_k\\,v_\\theta(x_k,t_k,c)$，误差累积近似为 $\\sum_k \\Delta_k^2\\,\\|\\partial_t v\\|$，故 $\\Delta$ 的平方权重决定了总误差——把 $\\Delta$ 减半的收益是四倍误差下降，但步数翻倍、时延翻倍，这是 SLO 权衡的数学形式。</p>\n<p>工程上，4–20 步的区间要按分辨率与 prompt 复杂度分层：低分辨率、简单 prompt 走 4–6 步；高分辨率或复杂条件走 12–20 步，必要时切二阶。分层不是拍脑袋，而是把失败模式前置拦截——复杂条件下 4–8 步 Euler 的纹理模糊是已知失效点，若不分层，画质不达标的请求会以重试形式回流，反而推高整体时延。显存侧，步数决定激活峰值的迭代次数，但真正占大头的是单步激活；因此 batch 组织应优先按单步峰值配，再按步数估总时延预算。</p>\n<p>具体例子：同一 batch 内混合简单与复杂 prompt 时，若统一用 6 步，复杂样本画质不达标；若统一用 16 步，简单样本白付时延。可行做法是按 prompt 复杂度打标、分桶调度，桶内共享 timestep 表，桶间独立计费时延——这把“步数选择”从单请求决策变成批调度决策，与连续批处理的思路一致。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-17\">十七 · 量化叠加下的速度场精度</h3>\n<p>速度场回归对量化误差的敏感度高于噪声预测，因为 $v=\\epsilon-x_0$ 是两个量级相近的量之差，减法会放大相对误差。FP8 下 DiT 的 GEMM 与注意力可叠加，NVFP4 混合精度进一步压缩权重与激活，但速度场输出的尾数位减少会直接进入 Euler 更新的增量项，少步时没有后续步去平均掉这部分误差。因此量化配置要与步数联动：步数越少，速度场输出精度越要保守，通常保留输出层与末端几层的高精度，把激进量化放在中段块。代价是显存带宽的节省被部分抵消，但换来的是少步下不出现结构性噪声。</p>\n<p>另一个交互点是 CFG 合并：$v_u$ 与 $v_c$ 各自量化后再相减，若两次前向的量化尺度不一致，外推项 $s(v_c-v_u)$ 会被系统性偏置放大。可行做法是让条件与无条件前向共享同一量化尺度（同一 calibration 统计），或在合并前把两者还原到统一尺度。这与“CFG 批合并与条件缓存”里讲的批合并是同一件事的两面：合并省的是前向次数，尺度统一保的是直线假设。</p>\n<p>具体例子：4 步 Euler、FP8 权重加 FP4 激活的配置下，若输出层也压到 FP4，末步增量误差直接可见为纹理块状伪影；把输出层留在 FP8、仅中段块用 FP4，同样步数下伪影消失，而显存节省仍保留大半。这说明量化粒度应按“是否进入最终增量”来分层，而不是全局一刀切。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-18\">十八 · 二阶修正的收益边界与实现代价</h3>\n<p>中点法的二阶修正把局部误差从 $O(\\Delta^2)$ 降到 $O(\\Delta^3)$，但收益有边界：当直线化残差本身很大时，二阶修正只能压低离散误差，压不住模型对常向量假设的偏离。换言之，中点法救的是“步长太大”，救不了“轨迹本来就弯”。因此在复杂条件、高分辨率场景，正确顺序是先加步数把 $\\Delta$ 压下来，再考虑升阶；反过来先升阶往往白付一倍前向。实现上，中点法需要 $x_\\text{mid}=x+\\frac{\\Delta}{2}v$ 与第二次前向，激活峰值约为 Euler 的 1.5–2 倍（保留中间量做修正），单请求时延近似翻倍。</p>\n<p>工程判断可写成一条规则：在时延预算内，先满足最小步数使画质达标，剩余预算再分配给阶数；若预算不足以同时满足，则降分辨率或减 batch，而不是硬上二阶。这与“阶段级扩散服务流水”的分段预算思路一致——把时延当约束、把步数与阶数当可调变量，而不是反过来。</p>\n<p>具体例子：单卡部署、SLO 为单请求时延上限，4 步 Euler 已接近多步 DDIM 画质时，二阶无收益；当 prompt 含多主体、空间关系复杂时，4 步 Euler 出现语义偏离，此时切到 8 步 Euler 的收益大于 4 步中点法，因为前者同时降低了 $\\Delta$ 与残差累积。只有在中步数（如 10–12 步）仍不达标时，中点法才进入选项。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-19\">十九 · 失败模式的公式定位</h3>\n<p>三类失败都能在公式里找到位置。其一，直线化不足：$v_\\theta$ 对 $\\epsilon-x_0$ 的拟合残差在复杂条件下偏大，Euler 的 $\\Delta^2\\|\\partial_t v\\|$ 项被残差主导，表现为 4–8 步纹理模糊——定位在训练分布覆盖，解法是分层步数或升阶。其二，CFG 次序错位：合并发生在更新之后，或 $s$ 随步漂移，等效速度不再恒定，$\\frac{dx_t}{dt}$ 与插值直线脱钩，表现为结构噪声与语义偏离——定位在调度器实现，解法是把合并钉死在更新之前并固定 $s$。其三，二阶开销失控：每步前向翻倍未纳入 SLO 预算，单请求时延超限——定位在阶数与步数的联合选择，解法是预算内先步数后阶数。</p>\n<p>把这三条写成可执行的检查项：调度器输出 timestep 表时校验 $\\Delta_k$ 非均匀性是否与分辨率档位匹配；CFG 合并函数强制在 Euler 更新前调用并断言 $s$ 在迭代内不变；二阶路径单独计费时延并设开关。这样公式不只是推导，而是服务端的约束条件——直线假设成立与否，最终由这些断言在运行时判定。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-20\">二十 · 直线假设失效时的二阶代价与分层步数</h3>\n<p>整流流的少步优势建立在 $v_\\theta(x_t,t,c)\\approx\\epsilon-x_0$ 这一直线近似上，而该近似只在训练分布覆盖的区域内成立。高分辨率、多主体、强文本约束的 prompt 会把真实传输轨迹重新拉弯，此时 4–8 步 Euler 的局部截断误差沿轨迹累积，表现为纹理糊化与细节塌陷——这不是数值 bug，而是模型对 $t$ 的 Lipschitz 常数在该区域变大。工程上的判别信号是：同一条 prompt 在 8 步与 20 步下的 latent 终态余弦距离超过阈值，即说明直线化不足，应触发步数升档而非盲目加 guidance。</p>\n<p>二阶中点法把每步前向从一次变为两次：先以 $v_\\theta(x_t,t,c)$ 走半步到 $x_{t-\\Delta/2}$，再用该点速度做全步修正 $x_{t-\\Delta}=x_t-\\Delta\\,v_\\theta(x_{t-\\Delta/2},t-\\Delta/2,c)$。误差阶从 $O(\\Delta^2)$ 降到 $O(\\Delta^3)$，但单请求时延近似翻倍，且需保留半步中间量，激活峰值上升。在 SLO 以首图时延为主的在线文生图服务里，这等价于用吞吐换画质：批大小须按显存峰值下调，二阶路径只应分配给高分辨率或复杂条件请求。</p>\n<table class=\"mini\"><thead><tr><th>求解器</th><th>每步前向</th><th>误差阶</th><th>显存峰值</th><th>适用档位</th></tr></thead><tbody><tr><td>Euler</td><td>1</td><td>$O(\\Delta^2)$</td><td>基准</td><td>4–8 步，中等条件</td></tr><tr><td>中点法</td><td>2</td><td>$O(\\Delta^3)$</td><td>升高（存半步量）</td><td>高分辨率/复杂 prompt</td></tr></tbody></table>\n<p>另一类失效来自 CFG 合并顺序：若把条件与无条件速度场在错误的 $t$ 或错误的插值点上线性组合，直线插值假设被破坏，少步输出出现结构噪声与语义漂移。可实现的约束是把 CFG 合并放在速度场输出之后、Euler 更新之前，并锁定 guidance scale 随 $t$ 的调度表，使 $v=\\epsilon-x_0$ 的参数化在整条轨迹上保持一致；FP8/FP4 量化叠加时，速度场幅值动态范围需按该合并后的张量校准，否则低精度舍入会放大少步误差。</p>\n<h3 id=\"alg-flow-matching-sampler-sec-21\">二十一 · 请求形态与批大小的耦合</h3>\n<p>整流流匹配采样器的负载配方，第一层约束来自请求形态本身。在线文生图是它的主战场：单条 prompt 进来，latent 从标准高斯采样，timestep 从 1 递减到 0，条件 embedding 与 latent 拼接送入 DiT，速度场 <em>v</em><sub>θ</sub>(<em>x</em><sub>t</sub>,<em>t</em>,<em>c</em>) 输出后按 scheduler 的离散表迭代 4–20 步，终态 <em>x</em><sub>0</sub> 送 VAE 解码。这条链路里，批大小不是自由参数，而是被显存与迭代步数共同挤压出来的结果。</p>\n<p>关键在于激活峰值随步数线性累积：二阶中点法要在每步保留 <em>x</em><sub>t</sub> 与中间修正量，才能做 <em>x</em><sub>t−Δ</sub> = <em>x</em><sub>t</sub> − Δ·<em>v</em><sub>θ</sub>(<em>x</em><sub>t</sub>,<em>t</em>) 的二阶外推，显存占用比一阶 Euler 高出一档。设单请求单步激活为 <em>A</em>，批大小为 <em>B</em>，步数为 <em>N</em>，求解器阶数为 <em>k</em>，则峰值近似为 <em>B</em>·<em>A</em>·<em>N</em>·<em>k</em> 的量级关系；<em>k</em>=2 时这条乘积直接翻倍。工程上因此出现两种配方：一阶 Euler 走大步数、大批量摊薄权重读取；二阶中点法走小批量、低步数换时延。前者吞吐高但单请求时延受步数拖累，后者时延好但每卡并发被显存压死。</p>\n<p>具体例子：一张 1024×1024 的 latent 在 FP8 速度场下做 8 步 Euler，批大小可以按显存余量推到较高档位；一旦切到中点法 6 步，同样显存只能容纳更小的批，因为每步要留两份状态做修正。这就是“批大小按显存与 4–20 步迭代组织”的实际含义——批不是拍脑袋定的，是步数与阶数的函数。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-22\">二十二 · 长度分布决定步数分层</h3>\n<p>这里的“长度”不是序列长度，而是 prompt 复杂度与输出分辨率的联合分布。整流流的直线化依赖训练分布：训练时见过的条件复杂度与分辨率区间，轨迹被拉得接近直线，4–8 步 Euler 就能逼近多步 DDIM 的画质；超出这个区间，轨迹重新弯曲，少步离散化误差迅速放大，纹理开始模糊。</p>\n<p>因此负载配方必须按分布分层，而不是全局一个步数。可以按 prompt token 数与目标分辨率把请求切成若干桶，每桶绑定一个步数档：短 prompt、中低分辨率走 4–6 步 Euler；长 prompt、高分辨率走 8–12 步，必要时切中点法。分层判据写成伪代码思路是：若 <em>L</em><sub>prompt</sub> 与 <em>R</em><sub>res</sub> 的联合分位超过阈值，则 <em>N</em> ← <em>N</em><sub>high</sub>，<em>k</em> ← 2；否则 <em>N</em> ← <em>N</em><sub>low</sub>，<em>k</em> ← 1。这个判断要在请求进入调度器时完成，不能等采样跑到一半再改。</p>\n<p>代价体现在两个方向。分层过粗，高复杂度请求被塞进低步数档，画质不达标，返工重采样把有效吞吐打回去；分层过细，桶太多导致批内请求步数不一致，连续批处理被迫按最大步数对齐，短请求白等长请求的尾部迭代，GPU 空转。一个具体场景：同一批里混入 4 步短 prompt 与 12 步长 prompt，批调度按 12 步推进，前 8 步里短请求的 lane 已经算完却占着显存与 SM 配额，等效吞吐下降。解法是按步数档分桶排队，而不是按到达顺序混批。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-23\">二十三 · 并发模型与 SLO 的张力</h3>\n<p>SLO 以单请求时延为主，这与吞吐导向的批策略天然冲突。单请求时延近似为 <em>N</em>·<em>k</em>·<em>t</em><sub>fwd</sub> 加上排队与 VAE 解码，其中 <em>t</em><sub>fwd</sub> 是单次 DiT 前向的墙钟时间；<em>k</em>=2 直接让时延翻倍。并发上升时，批内共享权重读取让 <em>t</em><sub>fwd</sub> 的边际成本下降，但排队时延上升，两条曲线交叉点就是容量规划的拐点。</p>\n<div class=\"formula\">$$T_{\\text{e2e}} \\approx W_q + N \\cdot k \\cdot t_{\\text{fwd}}(B) + t_{\\text{vae}}$$</div>\n<p>其中 <em>W</em><sub>q</sub> 是排队等待，<em>t</em><sub>fwd</sub>(<em>B</em>) 随批大小 <em>B</em> 增大而摊薄但非线性的部分来自显存带宽与 SM 占用。配方上，若 SLO 是硬时延上限，就把 <em>N</em>·<em>k</em> 钉死在小值、靠增大 <em>B</em> 提吞吐；若 SLO 是吞吐优先、时延给宽区间，就让 <em>N</em> 随复杂度上浮、<em>B</em> 随显存上浮。两种配方不能混用同一套调度参数。</p>\n<p>具体例子：一个在线服务把 8 步 Euler 作为默认档，并发上来后排队时延吃掉预算，运维的第一反应是加步数提画质——方向反了，应该先压 <em>N</em> 或降 <em>k</em>，把时延还给队列。二阶求解器增加每步前向次数，时延与显存开销上升，必须按 SLO 在步数与阶数之间做显式权衡，而不是两个都往上加。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-24\">二十四 · 负载不对时的三种失效</h3>\n<p>第一种失效是画质塌陷：复杂条件或高分辨率下训练分布直线化不足，轨迹仍弯曲，4–8 步 Euler 输出纹理模糊。这不是随机噪声，而是系统性欠采样——直线假设在弯曲段失效，Euler 的一阶截断误差在少步下无法被抵消。表现为细节糊、边缘软，语义大体对但质感不对。未按分辨率与 prompt 复杂度分层选步数时，这类请求会稳定地不达标。</p>\n<p>第二种失效是时延越界：二阶中点法每步前向次数翻倍，若没按 SLO 权衡阶数与步数，单请求时延直接超出预算。更隐蔽的是显存侧的连锁反应——中点法保留中间量做修正，激活峰值抬高，批大小被迫缩小，吞吐跟着掉，而调度器若仍按一阶的并发上限放请求进来，就会触发显存抖动甚至 OOM 重试。</p>\n<p>第三种失效最容易被忽视：速度场与 CFG 合并顺序错位，或 guidance scale 漂移，直线插值假设被破坏，少步输出出现结构噪声与语义偏离。整流流的速度场参数化与 CFG 合并天然兼容，但“兼容”不等于“随意”——合并发生在条件维度上，若在错误的 timestep 或错误的张量形状上做加权，等效于给直线轨迹注入一个非线性的偏置项，Euler 步长越大，偏置被放大得越厉害。表现为少步出图出现块状伪影或 prompt 语义漂移，而多步反而正常，这类症状常被误判为模型问题而非负载配方问题。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-25\">二十五 · 配方表的工程落地</h3>\n<p>把上述约束收拢成一张可执行的配方表，维度是请求形态、步数档、求解器阶数、批大小上限。在线文生图、条件复杂度中等、4–8 步 Euler 是基线档；高分辨率或长 prompt 升到 8–12 步并按需切中点法；批大小按显存峰值反推，二阶档单独设上限。量化可与 FP8/FP4 叠加，速度场参数化与 CFG 合并天然兼容，但量化后的数值误差会与少步离散化误差叠加，配方表里要把量化档位作为独立维度而不是默认项。</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>步数档</th><th>求解器</th><th>批大小取向</th><th>主要风险</th></tr></thead><tbody><tr><td>短 prompt、中低分辨率</td><td>4–6</td><td>Euler</td><td>按显存推高</td><td>画质边际不足</td></tr><tr><td>长 prompt、高分辨率</td><td>8–12</td><td>Euler 或中点</td><td>保守，留修正余量</td><td>时延越界</td></tr><tr><td>高复杂度条件</td><td>按需上浮</td><td>中点</td><td>小批</td><td>显存峰值与排队</td></tr></tbody></table>\n<p>落地时的判断点是：先定 SLO 形态（时延硬上限还是吞吐优先），再定 <em>N</em>·<em>k</em> 的乘积上限，最后用显存反推 <em>B</em>。反过来做——先定批大小再找步数——会在高复杂度请求上反复触发画质返工，有效吞吐反而更低。规模上限受每步前向次数与显存峰值约束，二阶求解器的时延开销更高，这条约束在配方表里是硬边界，不是可调项。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-26\">二十六 · 分桶调度与步数对齐</h3>\n<p>最后落到调度器的具体机制：连续批处理按步数档分桶，桶内请求共享同一张离散 timestep 表，桶间不混批。这样批内每个 lane 的迭代次数一致，不会出现短请求空转等长请求尾部的情况。桶的粒度取 2 步一档即可，过细反而增加调度开销。条件 embedding 在桶内可复用缓存，但 CFG 合并要在桶级统一 guidance scale，避免同批内 scale 漂移破坏直线假设。</p>\n<p>代价是桶间负载不均时 GPU 利用率下降：高步数桶排队而低步数桶空闲，需要按到达速率动态调桶的并发配额。工程判断是——当高复杂度请求占比上升，优先扩中点法桶的显存配额而不是全局加步数，因为全局加步数会把低复杂度请求也拖进长尾，SLO 被最慢的那条请求定义。配方表的稳定性来自这条分桶对齐机制，而不是来自某个固定的步数默认值。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-27\">二十七 · 负载配方：直线轨迹的适用域与失配代价</h3>\n<p>整流流采样器的负载配方不是“任何请求都能跑 4 步”的通用配方，而是一份围绕轨迹直线度签订的合同。合同的核心条款是：训练分布覆盖到的条件复杂度与分辨率区间内，速度场 $v_\\theta(x_t,t,c)$ 近似常向量，Euler 单步截断误差为 $O(\\Delta^2)$，4–8 步即可收敛；一旦请求落在合同之外，直线插值假设失效，误差不再随步数线性收敛，而是被弯曲轨迹放大。因此负载配方的第一件事是按分辨率与 prompt 复杂度分层，而不是按到达率统一批处理。在线文生图请求进入后，latent 从标准高斯采样、timestep 从 1 递减到 0，条件 embedding 与 latent 拼接送入 DiT，scheduler 的离散 timestep 表决定迭代 4–20 步——这张表必须随请求分层切换，不能全局固定。</p>\n<p>适合的请求形态有明确特征：条件复杂度中等、prompt 语义单一、分辨率处于训练主分布区间、对单请求时延敏感而对极限画质不敏感。这类请求用 4–8 步 Euler 即可接近多步 DDIM 画质，批大小按显存与迭代步数的激活峰值组织，单卡或张量并行即可承载。失配形态则相反：多主体组合、长 prompt、高分辨率、精细纹理要求，轨迹在少步下仍有弯曲，4–8 步 Euler 输出纹理模糊。此时必须增加步数或改用二阶中点法，而中点法每步前向次数翻倍，时延与显存开销同步上升。用一个小表刻画分层配方：</p>\n<table class=\"mini\"><thead><tr><th>请求分层</th><th>步数/阶数</th><th>批大小取向</th><th>主要代价</th></tr></thead><tbody><tr><td>中等条件、主分布分辨率</td><td>4–8 步 Euler</td><td>按显存峰值放大</td><td>吞吐优先，时延低</td></tr><tr><td>复杂条件、高分辨率</td><td>12–20 步或中点法</td><td>缩小批以保时延</td><td>每步前向翻倍，显存峰值上升</td></tr><tr><td>CFG 合并、guidance 漂移</td><td>先校正再定步数</td><td>不放大批</td><td>结构噪声，返工重采样</td></tr></tbody></table>\n<p>并发与批大小的组织必须与步数耦合。设单请求每步前向代价为 $C_{\\text{fwd}}$、步数为 $N$、批大小为 $B$，则单批时延近似 $T \\approx N \\cdot C_{\\text{fwd}}(B)$，而 $C_{\\text{fwd}}(B)$ 随批增大而上升但边际递减；二阶中点法把每步前向次数记为 $k=2$，时延变为 $T \\approx k N C_{\\text{fwd}}(B)$。这意味着在 SLO 以单请求时延为主的在线服务里，增大批大小换吞吐的窗口很窄：步数一旦从 8 升到 20，或阶数从 1 升到 2，批大小必须相应收缩，否则单请求时延直接超出预算。显存侧同理，4–20 步迭代的激活峰值决定批上限，二阶求解器还需保留中间量做修正，峰值进一步抬高。负载不对时的典型后果不是报错，而是静默的画质不达标与 SLO 违约：复杂条件请求被塞进 4 步批，输出纹理模糊；高分辨率请求与低分辨率请求混批，步数按低分辨率配置，高分辨率样本结构失真；CFG 合并顺序错位或 guidance scale 漂移，直线插值假设被破坏，少步输出出现结构噪声与语义偏离，只能返工重采样，实际吞吐被隐性拉低。</p>\n<p>工程判断落在调度器上：把分辨率与 prompt 复杂度作为分层键，为每层绑定独立的 timestep 表、阶数与批上限；对二阶求解器单独核算显存峰值与时延预算，不与 Euler 层混批；对 CFG 合并路径做一致性校验，guidance scale 漂移时先降批再重采样，而不是靠加步数掩盖。整流流是训练目标重参数化而非蒸馏，无需教师轨迹数据，但少步画质依赖训练分布直线化程度——这条边界决定了负载配方只能“分层适配”，不能“一刀切提速”。</p>\n<h3 id=\"alg-flow-matching-sampler-sec-28\">二十八 · 硬件档位：把每步前向次数当作第一约束</h3>\n<p>整流流采样器的部署成本结构，与自回归解码完全不同：它没有 KV 增长，也没有逐 token 的串行依赖，单请求的 GPU 时间几乎完全由「每步一次 DiT 前向 × 步数」决定。因此硬件选型的第一约束不是显存容量，而是每步前向的算力密度与单卡能否装下整张 DiT 的权重与激活峰值。Euler 一阶求解器每步一次前向，中点法每步两次（一次在 $x_t$ 处取 $v_1$，一次在 $x_t-\\tfrac{\\Delta}{2}v_1$ 处取 $v_2$，再合成 $x_{t-\\Delta}=x_t-\\Delta v_2$），这意味着二阶求解器把单请求时延的前向预算直接翻倍。工程判断很直接：若 SLO 允许的端到端时延为 $T$，单次前向耗时为 $\\tau$，则可用步数上界近似为</p>\n<div class=\"formula\">$$N_{\\text{step}}\\cdot k \\cdot \\tau \\le T - T_{\\text{vae}} - T_{\\text{net}},\\quad k\\in\\{1,2\\}$$</div>\n<p>其中 $k$ 为求解器阶数对应的每步前向次数，$T_{\\text{vae}}$ 为 VAE 解码时延，$T_{\\text{net}}$ 为请求调度与传输开销。这条不等式决定了档位：单卡档（单张 B200/B300）适合 4–8 步 Euler、中等分辨率在线服务，权重常驻、无跨卡通信；张量并行档（2 卡或 4 卡 TP）用于高分辨率或需要 12–20 步二阶求解的场景，代价是每步前向引入 all-reduce，通信量与隐藏维度和 TP 度成正比。TP 度提高会摊薄单卡显存压力，但每步的集合通信延迟会叠加到 $\\tau$ 上，在少步场景里这部分固定开销占比更高——步数越少，通信延迟越难被摊薄。因此一个可复现的配置思路是：先用单卡档跑 6 步 Euler 打底，只有当分辨率或 prompt 复杂度迫使步数上探、且单卡显存装不下激活峰值时才升到 TP 档，而不是默认上多卡。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-29\">二十九 · 并行拓扑：CFG 合并决定了并行维度的形状</h3>\n<p>整流流的速度场参数化与 CFG 合并天然兼容，这一点直接改写并行拓扑的设计。标准 CFG 需要条件分支与无条件分支两次前向，若朴素实现，每步前向次数从 $k$ 变成 $2k$，时延翻倍。工程上的做法是把两个分支在批维度上合并成一次前向：把条件 embedding 与无条件 embedding 拼成 batch=2 的输入，一次 DiT 调用同时产出 $v_{\\text{cond}}$ 与 $v_{\\text{uncond}}$，再在采样器侧做</p>\n<div class=\"formula\">$$v = v_{\\text{uncond}} + s\\,(v_{\\text{cond}} - v_{\\text{uncond}})$$</div>\n<p>合并后每步仍是一次前向，只是批内元素翻倍，激活峰值随之上升。这带来拓扑上的取舍：CFG 批合并适合放在单卡内做，因为批内两元素共享同一份权重、同一套 kernel 启动开销，合并收益最大；一旦拆到两张卡上分别跑 cond/uncond，就退化成两次独立前向加一次跨卡归约，收益消失。因此并行拓扑的推荐形状是「CFG 合并在卡内、TP 只沿隐藏维切分」，而不是「CFG 沿卡切分」。代价方面：批内翻倍使激活显存上升，若同时叠加 FP8/FP4 量化，权重的显存占用下降但激活仍是主要峰值来源，需要按 4–20 步迭代的激活峰值配置显存，二阶求解器还要额外保留 $v_1$ 与中间 $x_t-\\tfrac{\\Delta}{2}v_1$ 做修正，峰值进一步抬高。一个具体例子：6 步 Euler + CFG 合并，单步前向内 batch=2，激活峰值约为无 CFG 时的两倍量级，若显存吃紧，优先降分辨率或降 TP 外的批并发，而不是拆 CFG。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-30\">三十 · 量化方案：速度场输出的数值敏感度分层</h3>\n<p>量化在整流流采样器上的落点与自回归模型不同：这里没有 KV cache 需要量化，压力集中在 DiT 的 GEMM 与注意力，以及速度场输出的数值精度。可用事实给出的边界是「量化可与 FP8/FP4 叠加」，但速度场 $v_\\theta\\approx\\epsilon-x_0$ 是直接决定轨迹直线性的量，Euler 更新 $x_{t-\\Delta}=x_t-\\Delta v_\\theta$ 对 $v_\\theta$ 的误差是线性放大的：步长 $\\Delta$ 越大（少步场景），单步速度场误差对终态的影响越大。因此量化方案应分层：GEMM 与注意力走 FP8 甚至 NVFP4 以提升算力密度，而速度场输出的最后一层投影与采样器侧的累加保持较高精度，避免把量化噪声直接注入轨迹。伪代码思路：</p>\n<ul>\n<li>DiT 主体线性层与注意力：FP8/FP4 权重与激活，按块缩放；</li>\n<li>输出头（预测 $v_\\theta$ 的最后一层）：保留 FP8 或更高，不参与 FP4 分块；</li>\n<li>采样器累加 $x_t-\\Delta v_\\theta$：在 FP32 或高精度缓冲中做，避免少步下累积误差；</li>\n<li>CFG 合并的线性组合在采样器侧完成，不放进量化 kernel 内部。</li>\n</ul>\n<p>代价判断：量化提升的是每步前向的吞吐与能效，直接缩短 $\\tau$，从而放宽第一节的不等式、允许更多步数或二阶求解。但少步场景下量化误差不会被多步平均掉——步数越少，单步误差越难被后续步骤修正，这正是「复杂条件/高分辨率下少步出现纹理模糊」的数值侧成因之一。因此量化档位应与步数档位联动：4–6 步 Euler 用较保守的输出精度，12 步以上二阶求解可更激进地压 GEMM 精度，因为多步与二阶修正本身提供了误差平均。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-31\">三十一 · KV 策略：这里没有 KV cache，但有等价的状态预算</h3>\n<p>整流流采样器不存在自回归式的 KV cache，但存在等价的状态预算问题：每次迭代要保留 $x_t$、条件 embedding、以及二阶求解器所需的中间量。把「KV 策略」翻译到这个场景，实际是三件事：其一，条件 embedding 在 4–20 步内不变，应当在请求进入时算一次并常驻，而不是每步重算——这与条件缓存同源，但此处只强调它是采样器的固定状态而非可跳步的缓存；其二，二阶中点法需要保留 $v_1$ 与半步状态做修正，这部分中间量是显存峰值的直接来源，若并发批大小按一阶求解器配置，切到二阶就会溢出，必须按求解器阶数重算并发上限；其三，终态 $x_0$ 送入 VAE 解码前，latent 本身的显存占用相对 DiT 激活是小量，真正的峰值在 DiT 前向内部。工程上可复现的做法是把并发上限写成</p>\n<div class=\"formula\">$$\\text{batch}_{\\max}=\\left\\lfloor \\frac{M_{\\text{free}}-M_{\\text{weight}}-M_{\\text{cond}}}{M_{\\text{act}}(k,\\,H,\\,W)}\\right\\rfloor$$</div>\n<p>其中 $M_{\\text{act}}$ 是单请求在给定阶数 $k$、分辨率 $H\\times W$ 下的激活峰值。这个式子的意义是：分辨率与阶数是显存预算的两个独立乘数，升分辨率或升阶数都必须重算并发，不能沿用旧配置。一个具体例子：同一张卡上从 6 步 Euler 切到 6 步中点法，$k$ 从 1 变 2，激活峰值上升，若不同步下调并发，就会出现显存溢出而非单纯变慢——这是部署中最常见的配置漂移。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-32\">三十二 · 调度参数：步数分层与阶数分层是同一件事</h3>\n<p>调度参数的核心不是批大小本身，而是「按分辨率与 prompt 复杂度分层选步数」这条稳定性要求的落地方式。整流流的直线化依赖训练分布，复杂条件与高分辨率下轨迹仍有弯曲，4–8 步 Euler 会出纹理模糊；而二阶求解器能修正弯曲但每步前向翻倍。于是调度器应当把请求分成至少两档：常规档走 4–8 步 Euler、CFG 合并、单卡；复杂档走 12–20 步、按 SLO 决定是否切中点法。分档依据可以是 prompt 长度与条件结构、目标分辨率、以及是否命中已知的高弯曲条件类型。伪代码思路：</p>\n<ul>\n<li>请求解析 → 估计条件复杂度与分辨率 → 选步数档与阶数档；</li>\n<li>按档位查预计算的并发上限与量化档位（第一节与第四节的不等式）；</li>\n<li>连续批处理按档位分组，避免同批内混入不同步数与阶数导致 kernel 形状抖动；</li>\n<li>复杂档若时延超预算，优先降阶数（中点法→Euler）而非降步数，因为少步对画质的伤害更直接。</li>\n</ul>\n<p>代价上，分档会降低批内同质性、增加调度开销，但换来的是画质达标率与 SLO 命中率的稳定。反过来，不分档的统一配置在复杂条件上要么画质不达标、要么时延超预算，二者必居其一。这里的关键工程判断是：步数与阶数的权衡不是全局常数，而是每档独立的参数，且必须与量化档位、并发上限联动重算——任何一项单独调整都会破坏配置的自洽性。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-33\">三十三 · 一个可复现的配置思路</h3>\n<p>把上述约束串成一条可复现的路径，而不是给出一组固定数字。第一步，定 SLO：单请求时延为主，取端到端预算 $T$，扣除 VAE 解码与网络开销得到前向预算。第二步，定求解器：常规档 6 步 Euler（$k=1$），复杂档 12 步、按预算决定 Euler 或中点法（$k=2$），用第一节的不等式验证 $N_{\\text{step}}\\cdot k\\cdot\\tau\\le$ 前向预算，$\\tau$ 由量化档位下的实测单步前向决定。第三步，定量化：GEMM 与注意力走 FP8/FP4，输出头与采样器累加保高精度，按步数档联动——少步档保守、多步档激进。第四步，定拓扑：CFG 合并在卡内，TP 仅在单卡装不下激活峰值时启用，且 TP 度提高后重测 $\\tau$ 以反映集合通信开销。第五步，定并发：用第四节的显存式子按档位分别算 $\\text{batch}_{\\max}$，二阶档单独算，不与一阶档共用。第六步，验证失败模式：用复杂 prompt 与高分辨率样本跑常规档，确认是否出现纹理模糊；若出现，说明该样本应落入复杂档而非靠全局加步数解决。整条路径的自洽性检查点是：任何一档的参数改动，都必须重跑不等式与显存式子，因为步数、阶数、量化、并发四者通过 $\\tau$ 与 $M_{\\text{act}}$ 耦合在一起，孤立调参必然产生配置漂移。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-34\">三十四 · 部署配方的失效边界与系统代价</h3>\n<p>配方可复现的关键不在“选了什么”，而在“什么条件下它会崩”。硬件档位从单卡到张量并行，量化在 FP8/FP4 上叠加，KV 与激活按 4–20 步迭代峰值配置——这套组合的隐含前提是轨迹直线化成立。一旦 prompt 条件复杂或分辨率抬高，训练分布覆盖不足，直线插值假设退化，4–8 步 Euler 的离散误差不再被直线性压制，输出纹理模糊。此时唯一有效动作是分层选步数：按分辨率与条件复杂度把请求分档，低档 4–6 步、高档 12–20 步，而不是全局统一步数。分档本身引入调度代价——同一 batch 内混档会拉长尾请求时延，连续批处理需按档位分桶，桶内步数对齐才能避免整批等最慢者。</p>\n<p>二阶中点法把每步前向次数翻倍，时延近似按 <span class=\"formula\">$$T_{\\text{req}} \\approx N_{\\text{step}} \\cdot k_{\\text{eval}} \\cdot t_{\\text{fwd}} + t_{\\text{vae}}$$</span> 增长，其中 <span class=\"formula\">$$k_{\\text{eval}}$$</span> 为每步前向次数（Euler 为 1，中点为 2），<span class=\"formula\">$$t_{\\text{fwd}}$$</span> 为单次 DiT 前向时延。中点法还需保留 <span class=\"formula\">$$x_t$$</span> 与中间速度场做修正，激活峰值上升，显存按二阶路径单独预留。若 SLO 以单请求时延为主，步数与阶数的乘积就是预算约束：4 步中点与 8 步 Euler 前向次数相同，但中点在高曲率段误差更小，选哪个取决于轨迹弯曲程度而非直觉。</p>\n<p>量化叠加的边界在于速度场与 CFG 合并的顺序。FP8/FP4 压的是 DiT 权重与激活，CFG 合并若在量化后的速度场上做线性组合，guidance scale 漂移会直接破坏直线插值假设，少步输出出现结构噪声与语义偏离。正确顺序是先合并条件与无条件速度场、再走 Euler 更新，量化只作用于前向计算内部。下表给出配方各档位的代价对照：</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>步数/阶数</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>低延迟</td><td>4–6 步 Euler</td><td>画质余量小</td><td>高分辨率纹理模糊</td></tr><tr><td>均衡</td><td>8–12 步 Euler</td><td>时延线性增长</td><td>复杂条件语义偏离</td></tr><tr><td>高保真</td><td>12–20 步中点</td><td>前向翻倍、显存峰值高</td><td>单请求时延超预算</td></tr></tbody></table>\n<p>规模上限由每步前向次数与显存峰值共同约束：张量并行能摊开单卡显存，但每步前向的通信开销随并行度上升，二阶求解器把这份开销乘以二。工程判断是——先按分辨率与 prompt 复杂度定步数档，再用 SLO 反推阶数，最后才决定并行拓扑与量化档位；顺序颠倒会让配方在复杂请求上静默失效。</p>\n<h3 id=\"alg-flow-matching-sampler-sec-35\">三十五 · 每步前向次数：时延的第一性成本</h3>\n<p>整流流采样器的系统代价，先由“每步要跑几次 DiT”决定，而不是由步数单独决定。Euler 一步一次前向，中点法一步两次前向（先取 $v_\\theta(x_t,t,c)$ 到中点，再用中点速度修正）。因此二阶求解器把单请求的 DiT 前向总数直接翻倍，而步数表从 8 步降到 4 步只省一半——两者在同一量级上互相抵消，这就是“阶数与步数权衡”的算术本质。设单次前向时延为 $L_f$，步数为 $N$，每步前向次数为 $k\\in\\{1,2\\}$，则采样阶段时延近似为</p>\n<div class=\"formula\">$$T_{\\text{sample}} \\approx N \\cdot k \\cdot L_f + T_{\\text{vae}}$$</div>\n<p>其中 $T_{\\text{vae}}$ 是 VAE 解码，与采样阶段串行、不可被步数优化摊薄。工程判断很直接：当 $L_f$ 已被 NVFP4/FP8 GEMM 与 tcgen05 压到很低时，$T_{\\text{vae}}$ 在总时延中的占比上升，此时继续加步数换画质的边际收益迅速衰减，而二阶求解器翻倍的前向次数会把预算直接吃掉。一个具体例子：在线文生图 SLO 给定单请求时延上限，4 步 Euler 的采样段为 $4L_f$，4 步中点法为 $8L_f$；若 $8L_f$ 已逼近上限，则中点法必须降到 2–3 步才可行，而 2 步二阶修正对弯曲轨迹的补偿未必优于 6 步 Euler——这正是“按 SLO 权衡阶数与步数”要落在的具体比较上，而不是笼统地选二阶。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-36\">三十六 · 激活峰值与中间量：显存先于算力崩</h3>\n<p>规模上去以后，最先崩的通常不是算力而是显存。整流流采样在 latent 空间迭代，单步激活峰值由 batch、latent 分辨率、DiT 宽度与注意力中间量共同决定；Euler 只需保留当前 $x_t$，中点法则必须同时保留 $x_t$、中点估计与两支速度场输出以完成修正，激活峰值抬升。更关键的是批调度：连续批处理把不同步数的请求混在同一 batch 里时，batch 内必须按最大步数对齐或做掩码，短请求的显存被长请求“借走”，有效 batch 被拉低。显存约束可写成</p>\n<div class=\"formula\">$$\\text{batch}_{\\max} = \\left\\lfloor \\frac{M_{\\text{free}} - M_{\\text{weight}} - M_{\\text{kv/cache}}}{M_{\\text{act}}(N,k,\\text{res})} \\right\\rfloor$$</div>\n<p>其中 $M_{\\text{act}}$ 随分辨率近似平方增长、随 $k$ 线性增长。具体例子：同一张卡上，把 latent 分辨率提高一档，$M_{\\text{act}}$ 上升使 $\\text{batch}_{\\max}$ 下降，吞吐随之下降的幅度大于单请求时延的上升幅度——因为吞吐是 batch 与时延的乘积效应。工程上应把“分辨率分层”与“阶数分层”绑定：高分辨率请求走 Euler 少步、低分辨率请求才允许中点法，避免一个二阶请求把整批的显存水位抬高。VAE 解码的显存峰值是另一处独立尖峰，它与采样阶段不共享峰值，分块解码（见 VAE 分块并行解码条目）在这里承担的是把尖峰摊平的角色，而不是提速。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-37\">三十七 · 带宽：权重流与激活流的两种压力</h3>\n<p>Blackwell 上的推理带宽压力分两路。第一路是权重流：DiT 参数量大，单步前向要把权重从 HBM 搬进 SM，当 batch 偏小、算术强度不足时，采样阶段是带宽受限而非算力受限；此时量化（NVFP4/FP8，见 DiT NVFP4 混合精度条目）直接降低每步的字节数，收益近似线性。第二路是激活流：中点法多出的中间量要在 TMEM/寄存器与 HBM 之间往返，二阶修正的额外读写会与权重流争抢带宽。用算术强度粗看：</p>\n<div class=\"formula\">$$\\text{Intensity} = \\frac{2 \\cdot P \\cdot B}{S_w \\cdot P + S_a \\cdot B}$$</div>\n<p>$P$ 为参数量、$B$ 为 batch、$S_w$ 与 $S_a$ 为权重与激活的每元素字节数。batch 小时分母被 $S_w\\cdot P$ 主导，量化 $S_w$ 是唯一有效手段；batch 大时分母转向 $S_a\\cdot B$，此时二阶求解器的中间量写回成为瓶颈。具体例子：把 Euler 换成中点法，在同一 batch 下每步的激活读写量增加，若该 batch 已处于激活主导区，则单步时延的增幅超过前向次数翻倍所“应得”的增幅——多出来的部分就是中间量往返的带宽代价。这也是为什么二阶求解器在小 batch、权重主导区更划算，在大 batch、激活主导区反而更贵。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-38\">三十八 · 通信：张量并行下的每步同步点</h3>\n<p>当单卡放不下 DiT 而启用张量并行时，采样阶段的每一步都包含若干次集合通信（all-reduce/all-gather），步数 $N$ 与每步前向次数 $k$ 直接乘在通信次数上。NVLink 5 与 NCCL 把单次通信压得很低，但通信是同步点：它把一步内的计算切成段，段间的等待无法被连续批处理的重叠完全吸收，尤其在尾批（batch 不满）时通信延迟占比上升。通信代价可写成</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\!\\left(T_{\\text{comp}},\\, T_{\\text{comm}}\\right) + T_{\\text{sync}},\\quad T_{\\text{comm}} \\approx \\frac{S_{\\text{act}}}{BW_{\\text{nvl}}}$$</div>\n<p>具体例子：4 步 Euler 在 2 卡张量并行下每步含两次 all-reduce，共 8 次同步；换成 4 步中点法则 16 次。若单次同步的固定开销不可忽略，则二阶方案在并行度提高时被放大的不只是计算，还有同步次数——这就是“规模上去以后通信先咬人”的一条具体路径。缓解手段不是降低并行度，而是让 batch 足够大以摊薄 $T_{\\text{sync}}$，并把步数分层：并行度高时优先 Euler 少步，把二阶留给单卡或低并行度档位。分离式预填/解码的通信面（NIXL 搬运 KV 与 latent）与本段的集合通信是两套不同的代价，不要混算。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-39\">三十九 · 功耗与尾延迟：稳态之外的账</h3>\n<p>功耗约束在 NVL72 机柜尺度上表现为可持续频率：持续满载的采样服务会把 GPU 推到功耗上限，频率回落使 $L_f$ 上升，进而使按稳态 $L_f$ 做的容量规划失效。整流流采样器的功耗特征是“每请求固定次数的前向 + 一次 VAE 解码尖峰”，前者平稳、后者突发；把二阶求解器引入会同时抬高平稳段的功耗与尖峰的高度。容量规划应按功耗包络而非峰值算力折算有效 batch。尾延迟则来自三处叠加：一是 batch 内步数不齐导致的“最长请求决定批完成时间”；二是二阶请求混入 Euler 批造成的对齐开销；三是 VAE 解码尖峰与采样段争抢显存带宽。尾延迟的放大可用分位数表述：</p>\n<div class=\"formula\">$$T_{p99} \\approx T_{p50} + \\Delta_{\\text{align}} + \\Delta_{\\text{spike}}$$</div>\n<p>具体例子：一个 4 步 Euler 请求与一个 4 步中点法请求被调度进同一批，批完成时间由中点法的 8 次前向决定，Euler 请求的 $T_{p50}$ 被拖到接近中点法水平，而它本可以早得多完成——这就是混批对齐的尾延迟代价。工程判断是：按阶数分队列，Euler 队列与中点法队列各自连续批处理，用调度器而非掩码来隔离两类负载；同时把 VAE 解码放进独立的分块流水，避免其尖峰进入采样段的功耗与带宽包络。规模上去以后先崩的顺序，在这套系统里通常是显存（激活峰值限制 batch）→ 通信同步（并行度抬高时）→ 功耗包络（稳态频率回落）→ 尾延迟（混批对齐），而算力本身往往不是第一个瓶颈。</p>\n\n\n<h3 id=\"alg-flow-matching-sampler-sec-40\">四十 · 直线轨迹撞上系统墙：每步前向、激活峰值与尾延迟的三重约束</h3>\n<p>整流流匹配把采样成本从“步数×弯曲积分”压缩成“步数×直线外推”，但压缩的是算法项，不是系统项。单请求代价仍可写成 <span class=\"formula\">$$T_{\\text{req}} = N_{\\text{step}}\\cdot k_{\\text{eval}}\\cdot T_{\\text{fwd}}(B, H\\cdot W, c) + T_{\\text{vae}}$$</span>，其中 <span class=\"formula\">$k_{\\text{eval}}$</span> 是每步前向次数（Euler 取 1，中点法取 2），<span class=\"formula\">$T_{\\text{fwd}}$</span> 随批大小 <span class=\"formula\">$B$</span>、latent 分辨率与条件 embedding 长度增长。4–8 步 Euler 之所以在在线文生图里成立，是因为它把 <span class=\"formula\">$N_{\\text{step}}\\cdot k_{\\text{eval}}$</span> 压到 4–8 次 DiT 前向；一旦为了复杂 prompt 或高分辨率把步数抬到 12–20，或切到中点法，前向次数立刻翻倍到 24–40，单请求时延按同一比例恶化。这里的边界不在 GPU 算力峰值，而在“每步前向次数”这个离散开关：它决定容量规划里单卡能塞进多少个并发请求，也决定尾延迟分布的形状。</p>\n<p>显存侧先崩的通常不是权重，而是激活峰值与二阶求解器的中间量。DiT 在 latent 拼接条件 embedding 后做整段注意力，激活随 <span class=\"formula\">$B\\times$</span> token 数线性上涨，而中点法必须在同一步内保留 <span class=\"formula\">$x_t$</span> 与一次修正后的中间态才能做二阶外推，等于把每步的驻留激活抬到 Euler 的约两倍。工程上这意味着：同一张卡、同一批大小，Euler 4 步能跑满的并发，中点法 8 步往往要降批或切张量并行。降批直接吃掉吞吐，切张量并行则把每步前向从“单卡本地”变成“带集合通信的同步点”——NVLink 5 域内还好，跨节点走 NCCL 时每步一次 all-reduce 就把直线轨迹的少步优势磨掉一截。规模上去以后，第一个崩的指标往往不是单请求时延，而是**尾延迟**：批里混入一个高分辨率、长条件的请求，它的步数被分层策略抬到 20 步且走中点法，整批被它拖到同步点，P99 被单条慢请求拉长，而均值几乎不动。</p>\n<p>带宽与功耗的账要分开算。权重侧，FP8/FP4 量化能把速度场网络常驻显存压下来，让更多并发挤进同一张卡；但每步仍要读一遍权重、写一遍激活，HBM 带宽在少步下不是瓶颈，在 20 步、大 batch 下就变成 <span class=\"formula\">$N_{\\text{step}}\\cdot B\\cdot$</span> 激活读写的主导项。功耗侧更隐蔽：少步意味着单请求的能耗被摊薄，但为了守住 SLO 而提高并发、拉高时钟，整机功耗反而随吞吐上升；中点法的双前向让每张图的焦耳数近似翻倍，在 NVL72 机柜的功率封顶下，这直接换算成“每机柜每小时能出多少张图”的上限。调度器若只按步数排队、不按 <span class=\"formula\">$k_{\\text{eval}}$</span> 与分辨率加权，就会出现高阶请求挤占低阶请求、机柜功率触顶降频、尾延迟雪崩的连锁。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的系统项</th><th>工程动作</th></tr></thead><tbody><tr><td>步数 4–8 → 12–20</td><td>单请求时延、批同步点</td><td>按分辨率/prompt 复杂度分层选步数</td></tr><tr><td>Euler → 中点法</td><td>激活峰值、每步前向次数</td><td>仅在画质不达标的分层启用二阶</td></tr><tr><td>批大小抬升</td><td>HBM 激活读写、尾延迟</td><td>按 <span class=\"formula\">$k_{\\text{eval}}$</span> 加权排队，隔离慢请求</td></tr><tr><td>跨节点张量并行</td><td>每步 all-reduce 同步开销</td><td>优先域内并行，减少步内通信</td></tr></tbody></table>\n<p>失效条件要落到具体机制上：直线化依赖训练分布，复杂条件或高分辨率下轨迹仍弯曲，4–8 步 Euler 输出纹理模糊——这不是“画质略差”，而是画质不达标且无法靠调 guidance 救回；速度场与 CFG 合并顺序错位或 guidance scale 漂移，会直接破坏直线插值假设，少步输出出现结构噪声与语义偏离，此时加步数也未必收敛，因为速度场本身已被错误条件污染。工程判断是：把“步数×阶数”当作一等调度维度，而不是事后调参；对每个分辨率档位与 prompt 复杂度分层预设 <span class=\"formula\">$N_{\\text{step}}, k_{\\text{eval}}$</span> 组合，用 SLO 反推单卡并发上限，再决定是否值得为少数难例开中点法。规模上限因此不在算法侧，而在“每步前向次数×激活峰值×同步点”三者乘积所允许的尾延迟预算里。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-41\">四十一 · 规模放大后先崩在哪：每步前向次数、激活峰值与尾延迟的耦合</h3>\n<p>整流流采样器的吞吐上限不在步数本身，而在“每步前向次数 × 批内并发 × 激活峰值”这三者的乘积。Euler 每步一次 DiT 前向，中点法每步两次（一次在 $x_t$ 处取 $v_1$，一次在 $x_t-\\tfrac{\\Delta}{2}v_1$ 处取 $v_2$，再合成 $x_{t-\\Delta}=x_t-\\Delta v_2$），因此二阶求解器的单请求时延近似翻倍，同时必须保留 $v_1$ 与中间 latent 做修正，显存峰值抬升。设单步前向时延为 $\\tau$、步数为 $N$、每步前向次数为 $k$，则单请求时延 $T\\approx N\\cdot k\\cdot\\tau$；在固定 SLO 下可承载的批大小 $B$ 受显存约束 $B\\le \\dfrac{M_{\\text{free}}-M_{\\text{weight}}}{k\\cdot a_{\\text{act}}}$，其中 $a_{\\text{act}}$ 是单样本单次前向的激活占用。规模上去后，$k=2$ 先吃掉显存余量，再吃掉时延预算，这是第一个崩点。</p>\n<p>第二个崩点是带宽而非算力。4–20 步迭代意味着每步都要把 latent、条件 embedding 与 DiT 权重重新过一遍显存层级；当批大小被推到显存边界，权重读取与激活写回的 HBM 流量随 $B$ 线性增长，而算力利用率因每步只做一次轻量更新（Euler 仅一次向量减）而偏低，形成“带宽饱和、SM 空转”的形态。此时增大批并不能摊薄单请求成本，反而把尾延迟拉长：同一 batch 内所有请求必须等最慢的那条走完 $N$ 步，若按 prompt 复杂度分层失败、把复杂条件请求与简单请求混批，整批被高步数请求拖住，P99 时延由最长路径决定而非平均路径。</p>\n<p>第三个崩点是通信与功耗。张量并行下每步前向都要做激活的 all-reduce，步数 $N$ 与每步前向次数 $k$ 直接乘在通信次数上：$N\\cdot k$ 次集合通信，NVLink 上的时延随步数线性累加，跨节点时更明显；功耗侧，DiT 前向是持续高占用的密集计算，$k=2$ 使单位时间能耗上升，在功耗封顶的机柜里表现为频率回落、$\\tau$ 变大，进一步压缩 SLO 余量。工程判断是：把二阶求解器限制在高分辨率、复杂条件的少数请求上，按分辨率与 prompt 复杂度分层选步数（简单请求 4–6 步 Euler，复杂请求 8–12 步或中点法），并在调度层做同 step 数、同 solver 的批聚合，避免混批拖尾；CFG 合并顺序与 guidance scale 必须与训练时的直线插值假设一致，否则少步输出出现结构噪声，画质不达标会迫使运维抬步数，反过来吃掉全部吞吐余量。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先饱和的资源</th><th>表现</th></tr></thead><tbody><tr><td>批大小推到显存边界</td><td>HBM 带宽</td><td>SM 利用率下降，单请求成本不摊薄</td></tr><tr><td>启用中点法</td><td>时延与激活显存</td><td>$T$ 近似翻倍，$B$ 上限减半</td></tr><tr><td>张量并行跨节点</td><td>集合通信</td><td>$N\\cdot k$ 次 all-reduce 累加尾延迟</td></tr><tr><td>功耗封顶</td><td>频率</td><td>$\\tau$ 上升，SLO 余量收窄</td></tr></tbody></table>\n<h3 id=\"alg-flow-matching-sampler-sec-42\">四十二 · 精度失效：弯曲轨迹的三种可观测征兆</h3>\n<p>整流流采样器的精度失败不是随机噪声，而是有明确物理来源的：训练分布直线化不足，导致推理时速度场 $v_\\theta(x_t,t,c)$ 与真实传输方向偏离，Euler 更新 $x_{t-\\Delta}=x_t-\\Delta\\,v_\\theta$ 的局部截断误差在少步下被放大。工程上要区分三种征兆，因为它们的回滚动作完全不同。</p>\n<p>第一种是<b>纹理模糊</b>：4–8 步 Euler 在复杂 prompt 或高分辨率下输出细节塌陷，表现为高频能量缺失而非结构错乱。诊断手段是在采样轨迹上记录每步的 latent 统计量——相邻步 $x_t$ 与 $x_{t-\\Delta}$ 的余弦相似度若在最后 2–3 步突然抬升（速度场趋于恒定），说明轨迹已提前“直线化饱和”，剩余步数在做无效积分。第二种是<b>结构噪声</b>：CFG 合并顺序错位或 guidance scale 漂移破坏直线插值假设，输出出现块状伪影与语义偏离，这类失败在 batch 内表现为个别样本异常而其余正常，因为 CFG 的条件缓存按 batch 槽位复用，槽位错配即污染。第三种是<b>二阶求解器的时延溢出</b>：中点法每步前向次数翻倍，若未按 SLO 在阶数与步数间权衡，单请求时延直接超预算——这不是画质问题，是容量问题，但监控上常与精度告警混在同一指标里。</p>\n<p>监控设计上，把“画质”拆成可计算的代理指标：latent 轨迹的步间位移范数 $\\lVert x_{t-\\Delta}-x_t\\rVert$ 序列应在中段单调下降、末段收敛，若出现非单调抖动即为轨迹弯曲信号；同时记录终态 $x_0$ 送入 VAE 前的动态范围，越界即触发精度回滚。代价上，这些统计量每步只增加一次归约，相对 DiT 前向的算力可忽略，但需要额外一次显存读写，在 4–20 步迭代的激活峰值上叠加约一个 latent 张量的带宽开销。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-43\">四十三 · OOM 与显存峰值的定位路径</h3>\n<p>整流流采样的显存失败有两个高发点，且都不在稳态。第一是<b>二阶求解器的中间量保留</b>：中点法需要 $x_t$ 与 $v_\\theta(x_t,t,c)$ 同时驻留以做修正，激活峰值比 Euler 高出一档；若按 Euler 的配方配置显存，切换到中点法即 OOM。第二是<b>批大小与步数的耦合</b>：批大小按显存与 4–20 步迭代组织，但步数本身不改变单步激活，改变的是调度器持有的在途请求数——连续批处理下，新请求在迭代中途插入会推高并发槽位，显存峰值出现在“批已满且步数未走完”的窗口。</p>\n<p>定位路径按数据流倒推：先看 OOM 发生在第几步。若在首步即失败，是 latent 与条件 embedding 拼接后的输入张量超限，属于批大小配置错误；若在中段失败，是二阶求解器的中间量叠加在途批，属于阶数与批大小的联合超配；若在末步附近失败，通常是 VAE 解码前的终态张量与解码器分块并行（该机制在其他片段展开）争抢显存。工程判断上，把批大小做成随阶数自适应：Euler 档位允许更大批，中点法档位按中间量系数下调，而不是全局统一配置。</p>\n<p>回滚动作要分级：一级回滚是把二阶降为一阶并保持批大小，牺牲画质换稳定；二级回滚是降批并保留阶数，牺牲吞吐换画质；三级才是降分辨率或减少步数。三级动作会直接改变输出分布，必须与精度告警联动，不能由 OOM 单独触发。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-44\">四十四 · 批抖动与路由不均的耦合</h3>\n<p>在线文生图请求的到达过程是重尾的，而整流流采样的服务时间由步数决定、步数又由 prompt 复杂度分层决定——这使批调度出现一种特有的抖动：同一 batch 内混合了 4 步的简单请求与 16 步的复杂请求，调度器必须等最慢槽位走完才能释放批，快请求的槽位被空转占用。抖动指标应监控<b>批内步数方差</b>与<b>槽位空转率</b>，前者高说明分层选步数没生效，后者高说明批释放策略过粗。</p>\n<p>路由不均来自另一个方向：条件 embedding 与 CFG 合并天然兼容，但 CFG 批合并把无条件与有条件前向拼进同一批，若路由层按请求而非按合并后的槽位分配 GPU，会出现单卡槽位密度不均——某些卡跑双倍前向而另一些卡空闲。诊断上对比各卡的 SM 占用率与批槽位计数的比值，偏离均值即路由失衡。</p>\n<p>代价上，批抖动直接吃掉吞吐：空转槽位不产出但占用显存与调度配额，等效于把有效批大小打折。回滚策略是启用按步数分桶的批队列，把 4–8 步与 9–20 步的请求隔离到不同批，代价是队列深度增加、首请求等待变长，需在 SLO 的单请求时延预算内权衡。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-45\">四十五 · 尾延迟尖刺的来源与监控</h3>\n<p>尾延迟尖刺在整流流服务里有三个可分辨来源。其一是<b>步数分层失效</b>：复杂条件或高分辨率请求被误判为简单请求、按 4–8 步执行，画质不达标后触发重试，重试请求携带更长步数重新入队，表现为 P99 时延的双峰分布——尖刺不是单次慢，而是重试链。其二是<b>二阶求解器的阶数切换</b>：按 SLO 动态在 Euler 与中点法间切换时，切换点附近的请求时延跳变，若切换阈值抖动则形成周期性尖刺。其三是<b>批释放的长尾</b>：批内最慢槽位决定释放时刻，重尾请求使批释放时刻的方差远大于单请求服务时间方差。</p>\n<p>监控上不能只看端到端 P99，要拆成三段：排队时延、采样迭代时延、VAE 解码时延。尖刺若集中在采样迭代段且与步数分布相关，指向分层失效；若与阶数切换时刻对齐，指向求解器抖动；若集中在批释放边界，指向调度策略。每段打点需要时间戳对齐，代价是每请求多几次时钟读取，可忽略。</p>\n<p>回滚动作：对重试链设置熔断，同一 prompt 连续两次画质告警即锁定步数下限，避免无限重试放大尾延迟；对阶数切换加滞回窗口，防止阈值附近反复横跳。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-46\">四十六 · 回滚的工程判断与灰度边界</h3>\n<p>回滚不是单一开关，而是按失败模式映射到最小改动面。精度类失败回滚到“步数分层表”的上一档，只改调度参数不动模型；OOM 类回滚到批大小与阶数的联合配置；批抖动类回滚到批队列分桶策略；尾延迟类回滚到重试熔断与阶数滞回。四类回滚的作用域不同，必须独立灰度，否则一次全局回滚会把已稳定的维度一起打回。</p>\n<p>灰度边界要绑定可观测指标：精度回滚的验收是 latent 轨迹步间位移序列恢复单调收敛；OOM 回滚的验收是显存峰值回到配置水位以下且批大小不降；批抖动回滚的验收是槽位空转率下降而首请求等待不超预算。每个验收条件都对应一个具体机制量，而不是笼统的“服务恢复”。</p>\n<p>最后落在一条工程判断上：整流流采样器的失败模式几乎全部源于“直线化假设被破坏”——无论是训练分布不足、CFG 合并错位还是阶数切换，本质都是速度场与直线插值的偏离。因此监控的第一性指标应始终是轨迹的直线度（步间位移方向的余弦一致性），其余指标都是它的下游投影；把回滚决策挂在这个指标上，比挂在端到端画质评分上更早、更准、代价更低。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-47\">四十七 · 少步直线假设失效时的诊断与回退路径</h3>\n<p>整流流匹配把采样误差的主要来源从“步数不足”转移到了“直线化不足”。Euler 更新 $x_{t-\\Delta}=x_t-\\Delta\\,v_\\theta(x_t,t,c)$ 的局部截断误差正比于轨迹曲率与步长平方，当训练分布未覆盖当前 prompt 或分辨率时，$v_\\theta$ 给出的方向在相邻 timestep 间发生偏转，4–8 步的离散误差不再被直线假设吸收，表现为纹理模糊、边缘振铃与语义漂移。诊断上不能只看单张图，要在服务端按分辨率桶与 prompt 复杂度桶分别统计“步数—画质”曲线：同一桶内把步数从 4 提到 8 若 FID/CLIP 类指标改善超过阈值，说明该桶落在弯曲轨迹区，应将该桶默认步数上调或切到中点法；若改善平缓，则瓶颈在 VAE 解码或量化，不在求解器。这一步的判断直接决定扩容预算花在步数还是花在二阶前向上。</p>\n<p>二阶中点法把每步前向次数翻倍，代价是单请求时延与激活峰值同步上升，因为修正项需要保留 $x_t$ 与 $v_\\theta(x_t,t,c)$ 的中间量。工程上按 SLO 做分层：在线交互请求锁 4–6 步 Euler，批量离线或高分辨率重绘才允许中点法，并用一个简单判据决定是否升级阶数——若该请求所属桶的历史 P99 时延余量大于一次额外前向的开销，则升级，否则维持一阶并接受画质折损。批抖动与尾延迟尖刺多源于此：同一 continuous batch 内混入二阶请求会拉长整个 batch 的 step 时间，把一阶请求一起拖进尾部长尾，因此调度器应按“求解器阶数×步数”做同质分组，而不是只按 token 或分辨率分组。</p>\n<p>另一类失败是速度场与 CFG 合并顺序错位。CFG 把条件与无条件速度场线性组合，若合并发生在错误的 timestep 或 guidance scale 在请求间漂移，直线插值假设被破坏，少步输出出现结构噪声与语义偏离，且这种偏离不会随步数增加而收敛——加步数只是把错误轨迹积分得更久。监控应把 guidance scale、实际生效步数、求解器阶数作为每次请求的标签写入指标，按标签切片看 P99 时延与失败率；路由不均则表现为某些 GPU 上高阶请求堆积，需在入口按标签做一致性哈希而非轮询。回滚路径要预先固化：每个模型版本绑定一组 scheduler timestep 表与默认阶数，灰度时以请求标签为粒度切流，一旦某桶的画质指标或尾延迟越界，直接把该桶回退到上一版本的步数表与一阶求解器，不改动其他桶，避免整机回滚带来的容量塌陷。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>回退动作</th></tr></thead><tbody><tr><td>直线化不足</td><td>分辨率/prompt 桶内加步数画质跃升</td><td>该桶步数上调或切中点法</td></tr><tr><td>二阶拖尾</td><td>batch step 时间拉长、P99 越界</td><td>按阶数同质分组，高阶限流</td></tr><tr><td>CFG 错位</td><td>加步数不收敛的结构噪声</td><td>回退 scheduler 表与 guidance 默认值</td></tr></tbody></table>\n<h3 id=\"alg-flow-matching-sampler-sec-48\">四十八 · 同族谱系与选择轴</h3>\n<p>整流流匹配采样器不是孤立存在的一支，它落在“少步扩散采样”这一族的中央位置，两侧分别是 DDIM 系的概率流积分器、一致性蒸馏（LCM）系的蒸馏采样器，以及 DPM-Solver 系的高阶求解器。选型的本质是回答三个问题：训练侧愿不愿意改目标函数、推理侧能容忍几步前向、画质预算落在纹理细节还是结构一致性上。整流流匹配的独特之处在于它把“拉直轨迹”写进了训练目标——$v_\\theta(x_t,t,c)\\approx \\epsilon - x_0$ 是重参数化而非蒸馏，因此不需要教师模型的轨迹数据，也不受教师容量上限约束；代价是直线化程度由训练分布决定，复杂条件与高分辨率下轨迹仍会弯。</p>\n<p>把选择轴拆成可量化的三条：步数预算 $N$、每步前向次数 $K$（Euler 为 1，中点法为 2）、以及训练改动量 $T$（零改动 / 目标重参数化 / 需教师蒸馏）。系统代价直接由 $N\\times K$ 决定单请求时延与激活峰值显存，而 $T$ 决定工程排期。整流流匹配的甜点区是 $N\\in[4,8]$、$K=1$、$T=$ 目标重参数化——即在已有 DiT 训练管线里替换插值与损失，不引入教师。凡是不允许改训练目标、只能用现成 checkpoint 的场景，整流流匹配直接出局，应转向蒸馏或高阶求解器。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-49\">四十九 · 与 DDIM 的对照：弯曲流与直线流</h3>\n<p>DDIM 在弯曲概率流上做离散积分，其更新写作 $x_{t-\\Delta}=x_t-\\Delta\\,v_\\theta(x_t,t,c)$ 形式相同，但 $v_\\theta$ 拟合的是真实概率流的速度，轨迹曲率大，离散化误差随 $\\Delta$ 增大迅速放大——这就是少步 DDIM 画质塌陷的根源。整流流匹配把同样的 Euler 公式用在近似直线的插值轨迹上，单步截断误差正比于轨迹二阶导，直线化后二阶导被压小，4–8 步即可接近多步 DDIM 画质。</p>\n<p>工程判断上，DDIM 的优势是零训练改动、checkpoint 生态成熟，适合“已有模型、步数预算宽松（20 步以上）”的存量服务；整流流匹配的优势是把步数压到个位数而无需蒸馏，适合新建管线或可重训的场景。代价侧的差别在于显存：两者激活峰值同量级，但 DDIM 多步意味着 KV/激活驻留时间更长，在长序列 latent 上更吃显存带宽；整流流少步则把压力转移到单步 GEMM 的算力密度上。一个具体例子：同一 DiT 主干、同一分辨率，20 步 DDIM 与 6 步整流流 Euler 的前向次数比约 3:1，单请求时延按前向次数近似线性缩放，整流流在 SLO 紧张时直接赢在次数上。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-50\">五十 · 与 LCM 一致性蒸馏的对照</h3>\n<p>LCM 走的是蒸馏路线：用教师模型的多步轨迹训练学生，把任意 timestep 的 $x_t$ 直接映射到 $x_0$，从而 1–4 步出图。整流流匹配走的是目标重参数化路线：不改网络结构，只把训练目标从“拟合概率流”换成“拟合直线插值速度场”。两者的少步画质来源不同——LCM 的画质上限受教师轨迹覆盖度约束，蒸馏数据要覆盖条件空间，工程上要维护教师推理管线；整流流的画质上限受训练分布直线化程度约束，不需要教师，但复杂 prompt 下直线假设被破坏时没有教师兜底。</p>\n<p>系统代价的对照很直接：LCM 训练阶段要跑教师前向，训练吞吐被教师推理拖住，且蒸馏数据的条件覆盖是隐性的质量风险；整流流训练阶段只是换损失，训练成本与基线 DiT 同量级。推理侧两者都能压到 4 步以内，但 LCM 在 1–2 步的极端区间更稳，整流流在 4–8 步区间更稳。选型规则：若步数预算被压到 2 步以下且允许维护教师，选 LCM；若步数预算 4–8 步、希望训练管线简单、且条件复杂度中等，选整流流匹配。二者并非互斥——整流流训练出的直线化主干可以作为 LCM 的初始化，进一步压步数，但这属于组合策略，不在单算法选型表内。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-51\">五十一 · 与高阶求解器的对照：阶数换步数</h3>\n<p>DPM-Solver 系用二阶甚至三阶求解器在弯曲流上换精度，每步前向次数 $K&gt;1$，用 $N\\times K$ 的总前向数换取低离散误差。整流流匹配的中点法正是这一思路的轻量版：$x_{t-\\Delta}=x_t-\\Delta\\,v_\\theta(x_t,t,c)$ 之后用中点处的速度做二阶修正，$K=2$。区别在于整流流的中点法作用在已经拉直的轨迹上，二阶修正的收益比在弯曲流上小——直线轨迹的一阶 Euler 已经够准，二阶修正主要救的是残余弯曲段。</p>\n<div class=\"formula\">$$\\text{总前向数}=N\\times K,\\quad \\text{单请求时延}\\approx N\\times K\\times t_{\\text{fwd}}+t_{\\text{VAE}}$$</div>\n<p>代价权衡落在 SLO 上：中点法把每步前向翻倍，时延与激活峰值显存同步上升，因为修正需要保留中间量。工程判断是分层选阶——低分辨率、简单 prompt 用 4–6 步 Euler（$K=1$）；高分辨率或复杂条件用 8 步 Euler 或 4–6 步中点法（$K=2$），把总前向数控制在 8–12 次以内。超过这个区间，高阶求解器在弯曲流上的优势开始压过整流流的直线假设，此时应换用 DPM-Solver 而非继续加步数。一个具体例子：同一高分辨率请求，6 步 Euler 出现纹理模糊时，先试 6 步中点法（总前向 12 次），若仍不达标再考虑 10 步以上高阶求解器，而不是盲目把 Euler 步数堆到 20。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-52\">五十二 · 决策表与适用条件</h3>\n<table class=\"mini\"><thead><tr><th>算法</th><th>训练改动</th><th>典型步数</th><th>每步前向</th><th>画质来源</th><th>适用条件</th></tr></thead><tbody>\n<tr><td>DDIM</td><td>无</td><td>20+</td><td>1</td><td>弯曲流小步积分</td><td>存量 checkpoint、步数预算宽松</td></tr>\n<tr><td>整流流 Euler</td><td>目标重参数化</td><td>4–8</td><td>1</td><td>直线化程度</td><td>可重训、条件复杂度中等、SLO 紧</td></tr>\n<tr><td>整流流中点法</td><td>目标重参数化</td><td>4–6</td><td>2</td><td>直线化 + 二阶修正</td><td>高分辨率、残余弯曲段</td></tr>\n<tr><td>LCM 蒸馏</td><td>需教师轨迹</td><td>1–4</td><td>1</td><td>教师覆盖度</td><td>极低步数、可维护教师管线</td></tr>\n<tr><td>DPM-Solver 高阶</td><td>无</td><td>8–15</td><td>2–3</td><td>高阶离散误差抑制</td><td>不可重训、弯曲流、画质优先</td></tr>\n</tbody></table>\n<p>表的读法是先看训练改动列：无改动一栏只能在 DDIM 与高阶求解器之间选，前者省算力后者省步数；可重训一栏才轮到整流流与 LCM。再看步数列：步数预算低于 4 且允许教师，LCM 是唯一解；4–8 步区间整流流 Euler 是默认解；高分辨率下轨迹弯曲，同区间改用中点法或抬高步数。最后看每步前向列：$K=2$ 的选项都要按 SLO 复核时延，因为 $N\\times K$ 才是真实成本。适用条件的硬边界是：整流流匹配不适合“不可重训 + 极低步数 + 复杂条件”三者同时成立的场景，此时直线假设、教师兜底、步数预算三者缺一，必须退到高阶求解器或多步 DDIM。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-53\">五十三 · 组合与降级路径</h3>\n<p>真实服务里选型不是单选。整流流匹配常与量化叠加——速度场参数化与 CFG 合并天然兼容，FP8/FP4 量化作用在 DiT 的 GEMM 上，不破坏直线插值假设；但量化误差会放大残余弯曲段的离散误差，因此量化档位要与步数档位联动：低比特量化配中点法或抬高步数，高比特量化可放心用 4 步 Euler。降级路径按 SLO 压力排序：正常态 4–6 步 Euler；画质告警时切 6 步中点法；时延告警时先降分辨率或减步数，而不是先降阶数，因为阶数减半省的是单步成本、步数减半省的是总前向数，后者对时延更直接。</p>\n<p>诊断信号要挂在具体机制上：若 4–8 步 Euler 输出纹理模糊且集中在复杂 prompt，判定为训练分布直线化不足，处置是分层选步数（按分辨率与 prompt 复杂度分档）或改中点法；若单请求时延超预算且发生在切中点法之后，判定为 $K=2$ 的前向翻倍未被 SLO 吸收，处置是回退 Euler 并降步数；若少步输出出现结构噪声与语义偏离，判定为速度场与 CFG 合并顺序错位或 guidance scale 漂移，直线插值假设被破坏，处置是固定合并顺序并锁定 guidance scale 再做步数扫描。这三条诊断各自对应一个可观测指标——纹理频域能量、单请求 P99 时延、结构相似度——把选型从经验判断变成可回归的工程决策。</p>\n\n<h3 id=\"alg-flow-matching-sampler-sec-54\">五十四 · 选型边界：整流流匹配在算法族中的位置与失效面</h3>\n<p>把整流流匹配放进同族算法里比较，真正决定选型的不是“谁更先进”，而是三条约束的交点：少步下的离散化误差、训练侧是否需要教师轨迹、以及每步前向次数对时延的乘性放大。DDIM 沿弯曲概率流积分，步长稍大即误差迅速放大，服务端被迫用多步换画质；LCM 一类一致性蒸馏把多步教师压成少步学生，代价是必须产出教师轨迹数据、且蒸馏目标与教师采样器强绑定。整流流匹配走的是第三条路：用直线插值重参数化速度场，$v_\\theta(x_t,t,c)\\approx\\epsilon-x_0$，训练目标简单、收敛稳定，不需要教师轨迹，少步 Euler 误差天然更小。代价是这份“直”来自训练分布的先验，而非推理期的保证——直线化程度是学出来的，不是算出来的。</p>\n<p>失效面因此可以写得很具体。复杂条件或高分辨率下，训练分布覆盖不足，轨迹仍带弯曲，4–8 步 Euler 的输出落在纹理模糊上；此时若不做分层选步，画质直接跌破验收线。二阶中点法把每步前向次数翻倍，时延与显存峰值同步上升，若未按 SLO 在阶数与步数间权衡，单请求时延越预算。还有一类隐蔽故障：速度场与 CFG 的合并顺序错位或 guidance scale 漂移，会破坏直线插值假设，少步输出出现结构噪声与语义偏离——这不是数值误差，而是参数化前提被违反。用一条判据概括单步代价：</p>\n<div class=\"formula\">$$T_{\\text{req}} \\approx N_{\\text{step}}\\cdot k_{\\text{eval}}\\cdot t_{\\text{fwd}}(B) + t_{\\text{vae}},\\qquad k_{\\text{eval}}=1\\ (\\text{Euler}),\\ 2\\ (\\text{midpoint})$$</div>\n<p>其中 $t_{\\text{fwd}}$ 随批大小 $B$ 与激活峰值变化，二阶求解器还需保留中间量做修正，显存按 4–20 步迭代的激活峰值配置。工程判断落在决策表上：条件复杂度中等、分辨率常规、SLO 以单请求时延为主的在线文生图，选 4–8 步 Euler，量化可与 FP8/FP4 叠加，CFG 合并天然兼容；prompt 复杂或高分辨率，先加步数而非先升阶，因为升阶的时延代价是乘性的；只有在步数已加到 12–20 仍不达标、且时延预算尚有余量时，才引入中点法做二阶修正。需要教师轨迹可控或极端少步（个位数以下）时，转 LCM 类蒸馏；需要严格复现既有弯曲流采样行为时，留在 DDIM。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>首选</th><th>代价落点</th></tr></thead><tbody><tr><td>中等条件、4–8 步、时延敏感</td><td>整流流 Euler</td><td>少步纹理风险，需分层选步</td></tr><tr><td>复杂 prompt / 高分辨率</td><td>整流流加步数至 12–20</td><td>时延线性增长</td></tr><tr><td>步数已满仍不达标</td><td>中点法二阶修正</td><td>每步前向翻倍、显存峰值上升</td></tr><tr><td>需教师可控的极少步</td><td>LCM 一致性蒸馏</td><td>教师轨迹数据与蒸馏绑定</td></tr></tbody></table>\n<p>规模上限由每步前向次数与显存峰值共同封顶：批大小按显存与迭代步数组织，二阶求解器的激活峰值更高，直接压缩可承载批大小，进而压低吞吐。因此整流流匹配的适用边界应表述为“4–20 步、条件复杂度中等的在线服务”，超出这条线不是算法变差，而是直线化先验不再覆盖当前输入分布——此时正确的动作是改采样器族或改步数分层策略，而不是在同一个速度场上继续加步硬扛。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2022 · 特征缓存与注意力稀疏</td></tr><tr><td>解决什么</td><td>扩散采样沿弯曲概率流积分，数值求解需小步长与多步数，且离散化误差随步数减少迅速放大，服务端难以在少步下保持画质。</td></tr><tr><td>一句话机制</td><td>用整流流把噪声到数据的传输拉直为近似直线轨迹，训练速度场 v_θ 拟合直线插值，推理时用 Euler/中点法沿直线积分…</td></tr><tr><td>代价与失效</td><td>直线化依赖训练分布，复杂条件/高分辨率下轨迹仍有弯曲，少步会出现纹理模糊；二阶求解器增加每步前向次数，时延与显存开销上升，需按 SLO 权衡</td></tr><tr><td>后继</td><td>潜空间一致性少步采样</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-flow-matching-sampler · 共 8 个片段</p>\n";break;}}})();
